    /// The connection of a connected test app.
    fn conn(a: &App) -> &crate::control::Connection {
        a.control.as_ref().expect("connected")
    }

    /// Connects, resets and waits for Idle.
    fn idle(a: &mut App) {
        use uc100::controller::State;
        let _ = a.update(Message::Connect);
        tick_until(a, 3.0, "E-stop after connecting", |s| {
            s.state == Some(State::EStop)
        });
        let _ = a.update(Message::MachineReset);
        tick_until(a, 3.0, "Idle after Reset", |s| s.state == Some(State::Idle));
    }

    /// An MDI line the driver refuses in every state, and how: busy while a
    /// line runs, unsupported otherwise.
    const MDI_MARK: &str = "G999";
    const MDI_MARK_REFUSED: [&str; 2] = ["MDI: machine is busy", "MDI: unsupported G999"];

    /// Runs one MDI line and waits until the machine is Idle again.
    fn mdi(a: &mut App, line: &str) {
        use uc100::controller::{Command, State};
        let seq = conn(a).snapshot.log_seq;
        conn(a).send(Command::Mdi(line.into()));
        // A line that runs may leave Idle for a single 4 ms driver loop, and
        // a refused one never leaves it. The driver takes commands in order,
        // so the refusal of a line sent after it says it has been taken up,
        // and Idle from then on says it is done.
        conn(a).send(Command::Mdi(MDI_MARK.into()));
        tick_until(a, 5.0, line, |s| {
            let new = usize::try_from(s.log_seq - seq).unwrap_or(usize::MAX);
            let taken = s
                .log
                .iter()
                .rev()
                .take(new)
                .any(|l| MDI_MARK_REFUSED.contains(&l.as_str()));
            taken && s.state == Some(State::Idle)
        });
    }

    /// An app with one simulated UC100 machine with the given profile.
    fn profile_app(dir: &std::path::Path, profile_text: &str) -> App {
        let mut a = App::from_workspace(dir.join("workspace.json"), None);
        let profile = dir.join("uc100.toml");
        std::fs::write(&profile, profile_text).unwrap();
        let mut m = Machine::new(3);
        m.p.insert("name".into(), "JY5800".into());
        m.p.insert("controller".into(), "UC100".into());
        m.p.insert("uc100_profile".into(), profile.display().to_string());
        m.p.insert("uc100_connection".into(), "Simulated".into());
        a.doc.machines.push(m);
        a
    }

    /// A wait's limit: `secs` of the driver's time. The simulated
    /// controller's timer counts the driver's 4 ms loops, which a loaded PC
    /// runs late while the simulated machine still moves in real time, so a
    /// limit in loops leaves a wait the time the load takes (#9). Wall time
    /// bounds it at ten times that, and a minute at least, should the driver
    /// stop.
    struct Deadline {
        loops: u64,
        seen: u64,
        last: Option<u16>,
        cap: std::time::Instant,
    }

    impl Deadline {
        fn new(secs: f64) -> Self {
            let wall = std::time::Duration::from_secs_f64(secs * 10.)
                .max(std::time::Duration::from_secs(60));
            Self {
                loops: (secs * 250.) as u64,
                seen: 0,
                last: None,
                cap: std::time::Instant::now() + wall,
            }
        }

        /// Counts the loops up to `s`; false once the limit has passed.
        fn within(&mut self, s: &uc100::controller::Snapshot) -> bool {
            if let Some(timer) = s.status.map(|st| st.timer) {
                if let Some(last) = self.last {
                    self.seen += u64::from(timer.wrapping_sub(last));
                }
                self.last = Some(timer);
            }
            self.seen <= self.loops && std::time::Instant::now() < self.cap
        }
    }

    /// Ticks until the machine snapshot satisfies `ok`; fails after `secs`
    /// of the driver's time (see `Deadline`).
    fn tick_until(
        a: &mut App,
        secs: f64,
        what: &str,
        ok: impl Fn(&uc100::controller::Snapshot) -> bool,
    ) {
        let mut deadline = Deadline::new(secs);
        loop {
            let _ = a.update(Message::Tick);
            let s = &a.control.as_ref().expect("connected").snapshot;
            if ok(s) {
                return;
            }
            assert!(
                deadline.within(s),
                "timed out waiting for {what}: {:?} {:?}",
                s.state,
                s.log
            );
            std::thread::sleep(std::time::Duration::from_millis(20));
        }
    }

    #[test]
    fn the_connected_machine_is_not_removed_and_disconnect_stays_on_the_control_page() {
        let dir = tempfile::tempdir().unwrap();
        let mut a = uc100_app(dir.path());
        a.page = Page::Control;
        let id = a.doc.machines[0].id.clone();
        let _ = a.update(Message::Connect);
        assert!(a.control.is_some());
        // Disconnect is in the Machine tab with the connection.
        let _ = a.update(Message::ControlTab(crate::ui::ControlTab::Machine));
        let _ = a.update(Message::DeleteMachine(id.clone()));
        assert_eq!(a.doc.machines.len(), 1);
        assert_eq!(
            a.status,
            "Disconnect before removing the connected machine."
        );
        assert!(page_texts(&a).iter().any(|t| t == "Disconnect"));
        // A connection whose machine is gone from the library still ends
        // from the Control page.
        a.doc.machines.clear();
        assert!(a.control_target().is_none());
        assert!(page_texts(&a).iter().any(|t| t == "Disconnect"));
        let _ = a.update(Message::Disconnect);
        assert!(a.control.is_none());
        assert!(!page_texts(&a).iter().any(|t| t == "Disconnect"));
        // Disconnected, the machine can be removed again.
        a.doc.machines.push(Machine::new(3));
        let other = a.doc.machines[0].id.clone();
        let _ = a.update(Message::DeleteMachine(other));
        assert!(a.doc.machines.is_empty());
    }

    #[test]
    fn connects_to_the_simulated_uc100_resets_and_e_stops() {
        use uc100::controller::State;
        let dir = tempfile::tempdir().unwrap();
        let mut a = uc100_app(dir.path());
        let _ = a.update(Message::Connect);
        assert!(a.control.as_ref().is_some_and(|c| c.simulated));
        tick_until(&mut a, 3.0, "E-stop after connecting", |s| {
            s.state == Some(State::EStop)
        });
        let identity = a
            .control
            .as_ref()
            .unwrap()
            .snapshot
            .identity
            .clone()
            .unwrap();
        assert_eq!(identity.hardware_id.as_deref(), Some("SIMULATED"));
        let _ = a.update(Message::MachineReset);
        tick_until(&mut a, 3.0, "Idle after Reset", |s| {
            s.state == Some(State::Idle)
        });
        let _ = a.update(Message::MachineEStop);
        tick_until(&mut a, 2.0, "E-stop", |s| s.state == Some(State::EStop));
        let _ = a.update(Message::Disconnect);
        assert!(a.control.is_none());
        // The simulator keeps its own saved state; the real machine's file is untouched.
        let id = a.doc.machines[0].id.clone();
        let state = dir.path().join("uc100");
        assert!(state.join(format!("{id}-simulated.toml")).exists());
        assert!(!state.join(format!("{id}.toml")).exists());
    }

    /// Like the JY5800 (X 0…390, Y 0…280, no switches, a PWM spindle without
    /// direction) but fast, with Z −80…0 for the fixture's drill, flood and
    /// no mist.
    const FAST: &str = r#"
[controller]
step_rate = "100kHz"
[motion]
junction_deviation = 0.02
arc_tolerance = 0.002
buffer_ms = 400
default_feed = 500
[axes.x]
steps_per_unit = 20.0
max_velocity = 60000.0
acceleration = 20000.0
step = { pin = 2 }
dir = { pin = 3 }
soft_min = 0.0
soft_max = 390.0
[axes.y]
steps_per_unit = 20.0
max_velocity = 60000.0
acceleration = 20000.0
step = { pin = 4 }
dir = { pin = 5 }
soft_min = 0.0
soft_max = 280.0
[axes.z]
steps_per_unit = 20.0
max_velocity = 30000.0
acceleration = 20000.0
step = { pin = 6 }
dir = { pin = 7 }
soft_min = -80.0
soft_max = 0.0
[outputs]
spindle_pwm = { pin = 16 }
flood = { pin = 8 }
"#;

    /// The fixture block's top setup on a simulated FAST machine whose AXIS
    /// CAM travel matches the profile: Facing (T1) then Drilling (T3), two
    /// tool runs.
    fn run_app(dir: &std::path::Path) -> App {
        run_app_on(dir, FAST)
    }

    fn run_app_on(dir: &std::path::Path, profile: &str) -> App {
        run_app_of(dir, profile, &[0, 3])
    }

    /// `run_app_on` with the fixture job's operations `ops` (by index):
    /// Face and Drill there.
    fn run_app_of(dir: &std::path::Path, profile: &str, ops: &[usize]) -> App {
        use crate::model::Strategy;
        let mut a = profile_app(dir, profile);
        let mut m = a.doc.machines.pop().unwrap();
        for (k, v) in [
            ("x", "390"),
            ("y", "280"),
            ("z", "80"),
            ("feed", "60000"),
            ("post_dwell", "0.2"),
        ] {
            m.p.insert(k.into(), v.into());
        }
        let (mut doc, mesh) = crate::post::fixture::job();
        let setup = &mut doc.setups[0];
        setup.operations = ops.iter().map(|&i| setup.operations[i].clone()).collect();
        for op in &mut setup.operations {
            op.p.insert("feed".into(), "30000".into());
            // A few seconds each: wide facing passes, holes without pecks.
            match op.strategy {
                Strategy::Face => {
                    op.p.insert("stepover".into(), "90".into());
                    op.p.insert("stepdown".into(), "5".into());
                }
                Strategy::Pocket | Strategy::Contour => {
                    op.p.insert("stepover".into(), "50".into());
                    op.p.insert("stepdown".into(), "10".into());
                }
                Strategy::Drill => {
                    op.p.insert("cycle".into(), "Drilling".into());
                    op.p.insert("coolant".into(), "Off".into());
                }
                _ => {}
            }
        }
        setup.machine = m.clone();
        doc.machines = vec![m];
        a.replace_document(doc, None);
        a.imported_mesh = Some(mesh);
        a.page = Page::Control;
        a
    }

    #[test]
    fn new_operations_take_the_coolant_the_machine_has() {
        for (profile, coolant) in [
            (FAST.to_string(), "Flood"),
            (FAST.replace("flood", "mist"), "Mist"),
            // The owner's JY5800 has neither output.
            (include_str!("../assets/jy5800.toml").to_string(), "Off"),
        ] {
            let dir = tempfile::tempdir().unwrap();
            let mut a = run_app_on(dir.path(), &profile);
            let _ = a.update(Message::AddOp(Strategy::Face));
            let op = &a.doc.setup().operations[a.selected.expect("added")];
            assert_eq!(get(&op.p, "coolant"), coolant, "{}", a.status);
        }
    }

    /// Idle with machine zero set where the machine starts and the work
    /// zero (the stock top centre) at machine X195 Y140 Z-20.
    fn zeroed(a: &mut App) {
        idle(a);
        zero(a);
    }

    /// Machine zero where the machine is, work zero at machine X195 Y140 Z-20.
    fn zero(a: &mut App) {
        let _ = a.update(Message::Machine(crate::control::Action::MachineZero(None)));
        tick_until(a, 3.0, "machine zero", |s| {
            s.referenced[..3].iter().all(|r| *r)
        });
        mdi(a, "G0 X195 Y140 Z-20");
        let _ = a.update(Message::Machine(crate::control::Action::WorkZero(None)));
        tick_until(a, 2.0, "work zero", |s| {
            s.work_pos[..3].iter().all(|v| v.abs() < 1e-6)
        });
    }

    /// Picks setup `si` to run and checks it here: tests do not run tasks.
    fn check_run(a: &mut App, si: usize) {
        let _ = a.update(Message::Run(crate::run::Action::Setup(si)));
        let epoch = run_of(a).epoch;
        let programs = crate::run::programs(&a.doc, a.part_mesh().unwrap(), si);
        let _ = a.update(Message::RunChecked(epoch, std::sync::Arc::new(programs)));
    }

    fn run_of(a: &App) -> &crate::run::Run {
        conn(a).run.as_ref().expect("a setup to run")
    }

    fn problems(a: &App) -> Vec<String> {
        run_of(a).problems(conn(a), &a.doc)
    }

    /// Ticks until the run satisfies `ok`; fails after `secs`.
    fn run_until(a: &mut App, secs: f64, what: &str, ok: impl Fn(&crate::run::Run) -> bool) {
        let mut deadline = Deadline::new(secs);
        loop {
            let _ = a.update(Message::Tick);
            let _ = a.view();
            if ok(run_of(a)) {
                return;
            }
            let s = &conn(a).snapshot;
            assert!(
                deadline.within(s),
                "timed out waiting for {what}: {:?} line {:?} at {:?} feed {} {:?} {:?}",
                s.state,
                s.current_line,
                s.machine_pos,
                s.feed_rate,
                run_of(a).outcome,
                s.log.iter().rev().take(5).collect::<Vec<_>>()
            );
            std::thread::sleep(std::time::Duration::from_millis(20));
        }
    }

    #[test]
    fn a_setup_runs_tool_run_by_tool_run_with_a_manual_tool_change() {
        use crate::run::Action as R;
        use uc100::controller::State;
        let dir = tempfile::tempdir().unwrap();
        let mut a = run_app(dir.path());
        zeroed(&mut a);
        let _ = a.view();
        check_run(&mut a, 0);
        let _ = a.view();
        let programs = run_of(&a).checked().unwrap_or_else(|| {
            panic!(
                "{:?}",
                run_of(&a).programs.as_deref().map(|p| p.as_ref().err())
            )
        });
        assert_eq!(programs.len(), 2);
        assert_eq!((programs[0].ops[0].tool, programs[1].ops[0].tool), (1, 3));
        assert!(problems(&a).is_empty(), "{:?}", problems(&a));
        // Tool run 1: progress names the operation and block being cut.
        let _ = a.update(Message::Run(R::CycleStart));
        tick_until(&mut a, 2.0, "the job", |s| s.state == Some(State::Run));
        let _ = a.view();
        let (p, op, block) = run_of(&a).progress(conn(&a).snapshot.current_line).unwrap();
        assert!(op == 0 && block < p.blocks.len());
        run_until(&mut a, 30.0, "tool run 1", |r| r.done[0]);
        tick_until(&mut a, 2.0, "Idle", |s| s.state == Some(State::Idle));
        assert!(run_of(&a).outcome.as_ref().unwrap().0);
        assert_eq!(run_of(&a).next, 1);
        // It ended at the clearance plane with the spindle and coolant off.
        let s = conn(&a).snapshot.clone();
        assert_eq!(
            (s.spindle, s.flood),
            (Some(uc100::gcode::Spindle::Off), false)
        );
        let p = &run_of(&a).checked().unwrap()[0];
        let plane = crate::post::clearance_plane(&p.blocks) - p.datum[2];
        assert!(
            (s.work_pos[2] - plane as f64).abs() < 1e-3,
            "{}",
            s.work_pos[2]
        );
        // The drill is another tool: Cycle Start waits for its Z touch-off.
        assert!(run_of(&a).tool_change().is_some());
        let _ = a.view();
        assert!(
            problems(&a)
                .iter()
                .any(|p| p.contains("touch off its Z first")),
            "{:?}",
            problems(&a)
        );
        let _ = a.update(Message::Run(R::CycleStart));
        assert!(run_of(&a).running.is_none());
        // The old tool on the reference surface (here, where it stands), then
        // the new one 2 mm lower on the same surface: it is 2 mm longer.
        let _ = a.update(Message::Run(R::RecordReference));
        let reference = run_of(&a).reference.unwrap();
        assert!((reference - s.work_pos[2]).abs() < 1e-9);
        mdi(&mut a, &format!("G0 Z{:.3}", reference - 2.));
        let _ = a.update(Message::Run(R::ZFromReference));
        tick_until(&mut a, 2.0, "the touch-off", |s| {
            (s.work_offset[2] - (-22.)).abs() < 1e-6
        });
        assert!(problems(&a).is_empty(), "{:?}", problems(&a));
        // Ready for Cycle Start: the tool change's check 4, the touch-off,
        // is done too (LIO-312).
        let _ = a.update(Message::ControlPhaseTab(
            crate::ui::ControlTab::ToolChange,
            false,
        ));
        let texts = page_texts(&a);
        let four = (texts.iter())
            .position(|t| t.starts_with("Touch the new tool"))
            .expect("check 4");
        assert_eq!(texts[four - 1], "✓", "{texts:?}");
        // X/Y zero must stay: moving it holds Cycle Start back.
        let _ = a.update(Message::Machine(crate::control::Action::WorkZero(Some(0))));
        tick_until(&mut a, 2.0, "X zero moved", |s| s.work_pos[0].abs() < 1e-6);
        assert!(
            problems(&a)
                .iter()
                .any(|p| p.contains("X/Y work zero changed"))
        );
        mdi(&mut a, "G10 L2 P1 X195");
        assert!(problems(&a).is_empty(), "{:?}", problems(&a));
        let _ = a.update(Message::Run(R::CycleStart));
        run_until(&mut a, 30.0, "tool run 2", |r| r.done[1]);
        let s = &conn(&a).snapshot;
        assert!(run_of(&a).outcome.as_ref().unwrap().0, "{:?}", s.log);
        // Lowered with the new Z offset: it ends at the plane in work Z.
        let p = &run_of(&a).checked().unwrap()[1];
        let plane = crate::post::clearance_plane(&p.blocks) - p.datum[2];
        assert!(
            (s.work_pos[2] - plane as f64).abs() < 1e-3,
            "{}",
            s.work_pos[2]
        );
        assert!(problems(&a).iter().any(|p| p.contains("Every tool run")));
    }

    /// The fixture job's Face, Pocket and Contour with the 10 mm flat, then
    /// its Drill: two tool runs, the first of three operations.
    fn ops_app(dir: &std::path::Path) -> App {
        run_app_of(dir, FAST, &[0, 1, 2, 3])
    }

    /// `check_run`, with the stock the check leaves (`run::check`),
    /// pictured in line, as in the smoke run.
    fn check_run_pictured(a: &mut App, dir: &std::path::Path, si: usize) {
        let _ = a.update(Message::Run(crate::run::Action::Setup(si)));
        answer_with_stock(a, dir, si);
    }

    /// Answers the run's check of setup `si` with the stock it leaves, as
    /// `App::check_run` does, pictures made in line.
    fn answer_with_stock(a: &mut App, dir: &std::path::Path, si: usize) {
        use std::sync::Arc;
        let (programs, left) = crate::run::check(&a.doc, a.part_mesh().unwrap(), si);
        let times = crate::run::Times::checked(&programs, &conn(a).config);
        answer_stock(a, dir, (Arc::new(programs), Arc::new(left), times));
    }

    /// A check's answer: its programs, the stock it leaves and their times.
    type StockCheck = (
        std::sync::Arc<Result<Vec<crate::post::Checked>, Vec<String>>>,
        std::sync::Arc<crate::run::Left>,
        Option<std::sync::Arc<crate::run::Times>>,
    );

    /// The run's check of setup `si` as `App::check_run` makes it, with the
    /// run's skips and steps taken as cut. It takes seconds: worked out
    /// before a tool run that it is answered during, which would otherwise
    /// cut on meanwhile to wherever the load lets it (LIO-313).
    fn stock_check(a: &App, si: usize) -> StockCheck {
        use std::sync::Arc;
        let (skips, steps) = (run_of(a).skips.clone(), run_of(a).all_cut());
        let (programs, left) =
            crate::run::check_steps(&a.doc, a.part_mesh().unwrap(), si, &skips, &steps);
        let times = crate::run::Times::checked(&programs, &conn(a).config);
        (Arc::new(programs), Arc::new(left), times)
    }

    /// Answers the run's check with `check`, pictures made in line.
    fn answer_stock(a: &mut App, dir: &std::path::Path, (programs, left, times): StockCheck) {
        let epoch = run_of(a).epoch;
        a.smoke_dir = Some(dir.to_path_buf());
        let _ = a.update(Message::RunCheckedStock(epoch, programs, left, times));
        a.smoke_dir = None;
    }

    /// Answers the run's check of setup `si` as `App::check_run` does, with
    /// the run's skips, the stock it leaves not pictured.
    fn answer_skips(a: &mut App, si: usize) {
        use std::sync::Arc;
        let epoch = run_of(a).epoch;
        let (skips, steps) = (run_of(a).skips.clone(), run_of(a).all_cut());
        let (programs, left) =
            crate::run::check_steps(&a.doc, a.part_mesh().unwrap(), si, &skips, &steps);
        let times = crate::run::Times::checked(&programs, &conn(a).config);
        let left = crate::run::Left {
            after: vec![],
            last: None,
            ..left
        };
        let _ = a.update(Message::RunCheckedStock(
            epoch,
            Arc::new(programs),
            Arc::new(left),
            times,
        ));
    }

    /// Asks to skip operation `oi` of setup 0 (`how`), and answers the check
    /// it asks for. Whether it asked.
    fn skip(a: &mut App, oi: usize, how: Option<crate::run::Skip>) -> bool {
        let _ = a.update(Message::Run(crate::run::Action::Skip(oi, how)));
        let asked = run_of(a).programs.is_none();
        if asked {
            answer_skips(a, 0);
        }
        asked
    }

    /// The operations (index in the setup) of each tool run the run sends.
    fn sent(a: &App) -> Vec<Vec<usize>> {
        (run_of(a).checked().unwrap().iter())
            .map(|p| p.indexes.clone())
            .collect()
    }

    /// Skipping an operation of the fixture's Face, Pocket, Contour and
    /// Drill checks the setup again: taken as cut, it is not sent and its
    /// time leaves the totals; its material left, the operations after it
    /// are checked from the stock with it; a tool run of skipped operations
    /// is gone; Face's material cannot be left, as every later operation
    /// cuts beneath it; each skip is undone; and none is taken while a tool
    /// run runs or holds.
    #[test]
    fn a_skipped_operation_is_checked_again_without_it_and_undone() {
        use crate::run::{Action as R, Skip::*, Stage::*};
        use uc100::controller::State;
        let dir = tempfile::tempdir().unwrap();
        let mut a = ops_app(dir.path());
        zeroed(&mut a);
        let _ = a.update(Message::Run(R::Setup(0)));
        answer_skips(&mut a, 0);
        assert_eq!(sent(&a), [vec![0, 1, 2], vec![3]]);
        let run = run_of(&a);
        let total = run.setup_time().unwrap();
        let pocket = run.op_times(0).unwrap()[1];
        assert!(pocket > 1., "{pocket}");
        let before = |a: &App, op: usize| -> f32 {
            let b = run_of(a).before.iter().find(|b| b.op == op).unwrap();
            b.stock.heights.iter().sum()
        };
        let drill_from = before(&a, 3);
        // Every operation after the Face cuts beneath it; nothing after the
        // Drill.
        let beneath = run.beneath.clone();
        assert!(
            beneath
                .iter()
                .any(|(oi, why)| *oi == 0 && why.contains("cuts beneath it")),
            "{beneath:?}"
        );
        assert!(!beneath.iter().any(|b| b.0 == 3), "{beneath:?}");
        assert!(!skip(&mut a, 0, Some(Left)));
        assert!(run_of(&a).skips.is_empty() && run_of(&a).checked().is_some());
        // The Pocket already cut, in the middle of tool run 1: the Face and
        // the Contour are sent, the start stays on the Face.
        assert!(skip(&mut a, 1, Some(Cut)));
        assert_eq!(sent(&a), [vec![0, 2], vec![3]]);
        let run = run_of(&a);
        assert_eq!(run.stages(0, None), [Next, ToCome]);
        assert!(
            !run.partway() && problems(&a).is_empty(),
            "{:?}",
            problems(&a)
        );
        let t = run.setup_time().unwrap();
        assert!(
            t < total - pocket / 2.,
            "{t} of {total}, the Pocket {pocket}"
        );
        let left = run.left(&conn(&a).snapshot).unwrap().setup;
        assert!((left - t).abs() < 1e-3, "{left} {t}");
        // The rows stay those of the whole setup.
        let rows = |a: &App| -> Vec<Vec<usize>> {
            let l = run_of(a).layout.as_deref().unwrap().as_ref().unwrap();
            l.iter().map(|p| p.indexes.clone()).collect()
        };
        assert_eq!(rows(&a), [vec![0, 1, 2], vec![3]]);
        // The Contour's material left: the Drill is checked from the stock
        // with it.
        assert!(!run.beneath.iter().any(|b| b.0 == 2), "{:?}", run.beneath);
        assert!(skip(&mut a, 2, Some(Left)));
        assert_eq!(sent(&a), [vec![0], vec![3]]);
        assert!(
            before(&a, 3) > drill_from + 1.,
            "{} {drill_from}",
            before(&a, 3)
        );
        // The Drill already cut: its tool run is gone.
        assert!(skip(&mut a, 3, Some(Cut)));
        assert_eq!(sent(&a), [vec![0]]);
        assert!(run_of(&a).setup_time().unwrap() < t);
        // The last operation sent is not skipped.
        assert!(!skip(&mut a, 0, Some(Cut)));
        // Each undone: the setup as it was.
        for oi in [3, 2, 1] {
            assert!(skip(&mut a, oi, None));
        }
        assert!(run_of(&a).skips.is_empty());
        assert_eq!(sent(&a), [vec![0, 1, 2], vec![3]]);
        assert!((run_of(&a).setup_time().unwrap() - total).abs() < 1e-3);
        assert_eq!(run_of(&a).stages(0, None), [Next, ToCome, ToCome]);
        // Not while tool run 1 runs or holds: the skips are not opened
        // either.
        let _ = a.update(Message::Run(R::CycleStart));
        tick_until(&mut a, 2.0, "the job", |s| s.state == Some(State::Run));
        assert!(!skip(&mut a, 2, Some(Cut)));
        let _ = a.update(Message::Run(R::More(Some(2))));
        assert_eq!(run_of(&a).menu, None);
        let _ = a.update(Message::Run(R::Hold));
        tick_until(&mut a, 3.0, "Hold", |s| s.state == Some(State::Hold));
        assert!(!skip(&mut a, 3, Some(Left)));
        let _ = a.update(Message::Run(R::More(Some(3))));
        assert_eq!(run_of(&a).menu, None);
        assert!(run_of(&a).skips.is_empty() && run_of(&a).checked().is_some());
        let _ = a.update(Message::Run(R::Stop));
        tick_until(&mut a, 3.0, "Idle", |s| s.state == Some(State::Idle));
        // Stopped, the skips open again; a project change clears them.
        let _ = a.update(Message::Run(R::More(Some(3))));
        assert_eq!(run_of(&a).menu, Some(3));
        assert!(skip(&mut a, 3, Some(Cut)));
        a.touch();
        assert!(run_of(&a).skips.is_empty() && run_of(&a).stale);
    }

    /// A hole of the Drill skipped as cut, then a start at a later one
    /// (LIO-275): each checks the setup again, keeping where Cycle Start
    /// starts; the start is the Drill's tool run, and waits for the work zero
    /// the holes before were drilled with and the drill's Z to be kept;
    /// Cycle Start rapids over the hole's entry, at the Drill's clearance,
    /// and waits there with the spindle on; Resume drills the rest.
    #[test]
    fn a_start_at_a_step_waits_over_its_entry_until_resume() {
        use crate::run::{Action as R, Stage, StepStage as S};
        use uc100::controller::State;
        let dir = tempfile::tempdir().unwrap();
        let mut a = run_app(dir.path());
        zeroed(&mut a);
        let _ = a.update(Message::Run(R::Setup(0)));
        answer_skips(&mut a, 0);
        let drill = run_of(&a).op_steps(1).expect("the Drill's holes").clone();
        assert!(
            drill.hole && drill.steps.len() >= 3,
            "{}",
            drill.steps.len()
        );
        let blocks = |a: &App| run_of(a).checked().unwrap()[1].blocks.len();
        let all = blocks(&a);
        // Hole 2 already drilled.
        let _ = a.update(Message::Run(R::Steps(Some(1))));
        let _ = a.update(Message::Run(R::PickStep(1, 1)));
        let _ = a.view();
        let _ = a.update(Message::Run(R::SkipSteps(true)));
        assert!(run_of(&a).programs.is_none());
        answer_skips(&mut a, 0);
        assert_eq!(run_of(&a).cut_steps, [(1, vec![1])]);
        assert!(blocks(&a) < all);
        assert_eq!(
            run_of(&a).step_stages(1, Stage::ToCome, None)[..3],
            [S::ToCome, S::Cut, S::ToCome]
        );
        assert_eq!((run_of(&a).next, run_of(&a).from), (0, 0));
        // Start at hole 3: the Drill's tool run is next, from there; the
        // holes before it are taken as cut by the start, the skip of hole 2
        // with them.
        let _ = a.update(Message::Run(R::PickStep(1, 2)));
        let _ = a.update(Message::Run(R::StartStep));
        answer_skips(&mut a, 0);
        let run = run_of(&a);
        assert_eq!((run.next, run.at_step()), (1, Some((1, 2))));
        assert!(run.cut_steps.is_empty());
        assert_eq!(
            run.step_stages(1, Stage::Next, None)[..3],
            [S::Before, S::Before, S::Next]
        );
        let _ = a.view();
        let wants = problems(&a);
        assert!(wants.iter().any(|p| p.contains("Keep it")), "{wants:?}");
        assert!(
            wants.iter().any(|p| p.contains("Same tool, keep Z")),
            "{wants:?}"
        );
        let _ = a.update(Message::Run(R::KeepZero));
        let _ = a.update(Message::Run(R::KeepToolZ));
        assert!(problems(&a).is_empty(), "{:?}", problems(&a));
        let _ = a.update(Message::Run(R::CycleStart));
        tick_until(&mut a, 5.0, "the pause over the entry", |s| {
            matches!(s.state, Some(State::Paused(_)))
        });
        let s = conn(&a).snapshot.clone();
        let Some(State::Paused(why)) = &s.state else {
            unreachable!()
        };
        assert!(why.contains("hole 3"), "{why}");
        // Over the entry, at the Drill's clearance, the spindle on.
        let sims = crate::run::simulated_for_tests(&a.doc, a.part_mesh().unwrap(), 0);
        let plan = &sims[1].1.as_ref().unwrap().plan;
        let entry = plan.moves[drill.steps[2].moves.start].from;
        let datum = run_of(&a).checked().unwrap()[1].datum;
        for k in 0..3 {
            assert!(
                (s.work_pos[k] - (entry[k] - datum[k]) as f64).abs() < 0.06,
                "{:?} {entry:?}",
                s.work_pos
            );
        }
        assert_ne!(s.spindle, Some(uc100::gcode::Spindle::Off));
        let _ = a.update(Message::Run(R::Resume));
        run_until(&mut a, 30.0, "the Drill's tool run", |r| r.done[1]);
        assert!(run_of(&a).outcome.as_ref().unwrap().0);
    }

    /// The Drill's tool run started at its operation, its work zero and
    /// tool kept: Cycle Start sent and running, `run_app`'s Face and Drill.
    fn drilling(a: &mut App) -> crate::run::OpSteps {
        use crate::run::Action as R;
        use uc100::controller::State;
        zeroed(a);
        let _ = a.update(Message::Run(R::Setup(0)));
        answer_skips(a, 0);
        let _ = a.update(Message::Run(R::Next(1)));
        let _ = a.update(Message::Run(R::KeepZero));
        assert!(problems(a).is_empty(), "{:?}", problems(a));
        let _ = a.update(Message::Run(R::CycleStart));
        tick_until(a, 3.0, "the Drill's tool run", |s| {
            s.state == Some(State::Run)
        });
        run_of(a).op_steps(1).expect("the Drill's holes").clone()
    }

    /// A uc100-server on 127.0.0.1 running the driver's simulator, as the
    /// Pi does its UC100, and `run_app`'s machine connecting to it across
    /// the network, this computer paired with it.
    fn pi_app(dir: &std::path::Path) -> (App, uc100_remote::Server) {
        let mut a = run_app(dir);
        let server = to_pi(&mut a, dir);
        (a, server)
    }

    /// Moves the machine of an app made by `profile_app` (its profile in
    /// `dir`) onto a uc100-server on 127.0.0.1 running the simulator, this
    /// computer paired with it.
    fn to_pi(a: &mut App, dir: &std::path::Path) -> uc100_remote::Server {
        let server = uc100_remote::Server::start(uc100_remote::ServerOptions {
            data: dir.join("pi"),
            listen: "127.0.0.1:0".parse().unwrap(),
        })
        .unwrap();
        // The Pi runs its simulator: the profile asks it to.
        let profile = dir.join("uc100.toml");
        let text = std::fs::read_to_string(&profile).unwrap();
        std::fs::write(
            &profile,
            text.replacen("[controller]", "[controller]\nsimulated = true", 1),
        )
        .unwrap();
        let _ = a.update(Message::MachineConnection(crate::control::PI));
        let _ = a.update(Message::PiAddress(server.addr().to_string()));
        let code = uc100_remote::data::Data {
            dir: dir.join("pi"),
        }
        .new_code()
        .unwrap();
        let token =
            uc100_remote::RemoteController::pair(&server.addr().to_string(), &code, "Test Mac");
        let _ = a.update(Message::PiPaired(token.map(|t| t.to_string())));
        assert!(a.status.starts_with("Paired"), "{}", a.status);
        server
    }

    /// The Pi's own snapshot: what its controller does, whatever this
    /// computer is connected to.
    fn pi_until(
        server: &uc100_remote::Server,
        secs: f64,
        what: &str,
        ok: impl Fn(&uc100::controller::Snapshot) -> bool,
    ) {
        let end = std::time::Instant::now() + std::time::Duration::from_secs_f64(secs);
        loop {
            if let Some(s) = server.snapshot()
                && ok(&s)
            {
                return;
            }
            assert!(
                std::time::Instant::now() < end,
                "timed out waiting on the Pi for {what}: {:?}",
                server.snapshot().map(|s| s.state)
            );
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
    }

    /// The owner's case: a tool run sent to the Pi goes on and finishes while
    /// this computer is disconnected, and closing the link does not
    /// disconnect the Pi's UC100 (no E-stop, no Disconnect). Connected again,
    /// the run follows it and takes the tool run as done.
    #[test]
    fn a_tool_run_on_the_pi_finishes_with_this_computer_disconnected() {
        use crate::run::Action as R;
        use uc100::controller::State;
        let dir = tempfile::tempdir().unwrap();
        let (mut a, server) = pi_app(dir.path());
        zeroed(&mut a);
        assert!(conn(&a).pi.is_some());
        let _ = a.update(Message::Run(R::Setup(0)));
        answer_skips(&mut a, 0);
        assert!(problems(&a).is_empty(), "{:?}", problems(&a));
        let _ = a.update(Message::Run(R::CycleStart));
        tick_until(&mut a, 5.0, "the tool run running on the Pi", |s| {
            s.state == Some(State::Run)
        });
        let _ = a.update(Message::Disconnect);
        assert!(a.control.is_none() && a.pi_run.is_some(), "{}", a.status);
        // The Pi carries on: still running a moment later, then done.
        std::thread::sleep(std::time::Duration::from_millis(300));
        let s = server.snapshot().unwrap();
        assert_eq!(
            s.state,
            Some(State::Run),
            "{:?}",
            s.log.iter().rev().take(5).collect::<Vec<_>>()
        );
        pi_until(&server, 60.0, "the tool run's end", |s| {
            s.state == Some(State::Idle) && s.program_outcome.as_ref().is_some_and(|o| o.ok)
        });
        // Connected again: the run takes the outcome the Pi kept.
        let _ = a.update(Message::Connect);
        run_until(&mut a, 10.0, "tool run 1 done", |r| r.done[0]);
        assert!(run_of(&a).outcome.as_ref().unwrap().0);
        // Closing never disconnected the UC100: the Pi's machine is still
        // enabled and referenced.
        let s = server.snapshot().unwrap();
        assert_eq!(s.state, Some(State::Idle));
        assert!(
            s.referenced[..3].iter().all(|r| *r),
            "an E-stop cleared the references"
        );
    }

    /// AXIS CAM closed and opened again while a tool run cuts on the Pi: it
    /// follows nothing, but the run bar's Hold, Resume and Stop now act on
    /// the Pi's machine.
    #[test]
    fn hold_and_stop_work_on_a_pi_tool_run_this_computer_did_not_follow() {
        use crate::run::Action as R;
        use uc100::controller::State;
        let dir = tempfile::tempdir().unwrap();
        let (mut a, server) = pi_app(dir.path());
        zeroed(&mut a);
        let _ = a.update(Message::Run(R::Setup(0)));
        answer_skips(&mut a, 0);
        let _ = a.update(Message::Run(R::CycleStart));
        tick_until(&mut a, 5.0, "running on the Pi", |s| {
            s.state == Some(State::Run)
        });
        let _ = a.update(Message::Disconnect);
        // As after a restart: the run is gone from this computer.
        a.pi_run = None;
        let _ = a.update(Message::Connect);
        tick_until(&mut a, 5.0, "the Pi running, seen again", |s| {
            s.state == Some(State::Run)
        });
        assert!(conn(&a).run.is_none());
        let _ = a.update(Message::Resized(iced::Size::new(1440., 900.)));
        let clicks = crate::ui::probe::clicks(
            crate::ui::run_bar(&a, conn(&a)),
            iced::Size::new(1440., 200.),
        );
        for want in [R::Hold, R::Stop] {
            assert!(
                clicks.iter().any(|m| matches!(m, Message::Run(r) if std::mem::discriminant(r) == std::mem::discriminant(&want))),
                "{want:?} not offered: {clicks:?}"
            );
        }
        let _ = a.update(Message::Run(R::Hold));
        pi_until(&server, 10.0, "Hold on the Pi", |s| {
            s.state == Some(State::Hold)
        });
        tick_until(&mut a, 5.0, "Hold seen", |s| s.state == Some(State::Hold));
        let _ = a.update(Message::Run(R::Resume));
        pi_until(&server, 10.0, "running again", |s| {
            s.state == Some(State::Run)
        });
        tick_until(&mut a, 5.0, "Run seen", |s| s.state == Some(State::Run));
        let _ = a.update(Message::Run(R::Stop));
        pi_until(&server, 10.0, "stopped on the Pi", |s| {
            s.state == Some(State::Idle) && s.program_outcome.as_ref().is_some_and(|o| !o.ok)
        });
    }

    /// A relay between this computer and the Pi that the test can cut: while
    /// cut, nothing crosses either way, as when Wi-Fi drops.
    struct Relay {
        addr: std::net::SocketAddr,
        cut: std::sync::Arc<std::sync::atomic::AtomicBool>,
    }

    impl Relay {
        fn to(server: std::net::SocketAddr) -> Relay {
            use std::sync::atomic::Ordering;
            let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
            let addr = listener.local_addr().unwrap();
            let cut = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
            let flag = cut.clone();
            std::thread::spawn(move || {
                for client in listener.incoming().flatten() {
                    let Ok(upstream) = std::net::TcpStream::connect(server) else {
                        continue;
                    };
                    for (mut from, mut to) in [
                        (client.try_clone().unwrap(), upstream.try_clone().unwrap()),
                        (upstream, client),
                    ] {
                        let flag = flag.clone();
                        std::thread::spawn(move || {
                            let mut buf = [0u8; 16384];
                            loop {
                                while flag.load(Ordering::SeqCst) {
                                    std::thread::sleep(std::time::Duration::from_millis(5));
                                }
                                let n = match std::io::Read::read(&mut from, &mut buf) {
                                    Ok(0) | Err(_) => break,
                                    Ok(n) => n,
                                };
                                // Cut while reading: what was read is lost.
                                if flag.load(Ordering::SeqCst) {
                                    continue;
                                }
                                if std::io::Write::write_all(&mut to, &buf[..n]).is_err() {
                                    break;
                                }
                            }
                            let _ = to.shutdown(std::net::Shutdown::Both);
                        });
                    }
                }
            });
            Relay { addr, cut }
        }

        fn set_cut(&self, on: bool) {
            self.cut.store(on, std::sync::atomic::Ordering::SeqCst);
        }
    }

    /// The link to the Pi drops while a tool run cuts: every tab says so
    /// over the page, the status line says it is the last known state, never
    /// "Connected", and the Pi finishes the tool run. With the link back the
    /// banner goes and the run takes the outcome.
    #[test]
    fn a_lost_link_to_the_pi_is_said_over_every_tab_while_the_pi_carries_on() {
        use crate::run::Action as R;
        use uc100::controller::State;
        let dir = tempfile::tempdir().unwrap();
        let (mut a, server) = pi_app(dir.path());
        let relay = Relay::to(server.addr());
        let _ = a.update(Message::PiAddress(relay.addr.to_string()));
        zeroed(&mut a);
        let _ = a.update(Message::Run(R::Setup(0)));
        answer_skips(&mut a, 0);
        let _ = a.update(Message::Run(R::CycleStart));
        tick_until(&mut a, 5.0, "running on the Pi", |s| {
            s.state == Some(State::Run)
        });
        relay.set_cut(true);
        let end = std::time::Instant::now() + std::time::Duration::from_secs(10);
        while !conn(&a).pi_down() {
            let _ = a.update(Message::Tick);
            assert!(
                std::time::Instant::now() < end,
                "the lost link never showed"
            );
            std::thread::sleep(std::time::Duration::from_millis(20));
        }
        let _ = a.update(Message::Tick);
        for tab in [crate::ui::ControlTab::Job, crate::ui::ControlTab::Machine] {
            let _ = a.update(Message::ControlTab(tab));
            shows(&a, &[crate::ui::PI_LOST]);
        }
        assert!(a.status.starts_with("No link to the Pi of"), "{}", a.status);
        assert!(!a.status.contains("Connected"), "{}", a.status);
        // The Pi carries on to the end of the tool run.
        pi_until(&server, 60.0, "the tool run's end", |s| {
            s.state == Some(State::Idle) && s.program_outcome.as_ref().is_some_and(|o| o.ok)
        });
        let _ = a.update(Message::Tick);
        assert!(
            conn(&a).pi_down() && a.status.starts_with("No link"),
            "{}",
            a.status
        );
        relay.set_cut(false);
        run_until(&mut a, 20.0, "tool run 1 done, the link back", |r| {
            r.done[0]
        });
        let _ = a.update(Message::Tick);
        assert!(!conn(&a).pi_down());
        lacks(&a, &[crate::ui::PI_LOST]);
        assert!(a.status.starts_with("Connected to"), "{}", a.status);
    }

    /// Stop after step on the Pi: armed while the Drill drills, then this
    /// computer disconnects at once. The Pi stops after a hole by itself,
    /// over the stock; connected again, the run says which hole.
    #[test]
    fn the_pi_stops_after_a_step_with_this_computer_gone() {
        use crate::run::Action as R;
        use uc100::controller::State;
        let dir = tempfile::tempdir().unwrap();
        let (mut a, server) = pi_app(dir.path());
        let drill = drilling(&mut a);
        let _ = a.update(Message::Run(R::StopAfterStep));
        assert!(run_of(&a).stop_after, "{:?}", conn(&a).pi_note);
        // Wait for the Pi to hold it armed, then leave.
        let mut deadline = Deadline::new(5.);
        loop {
            let _ = a.update(Message::Tick);
            let armed = conn(&a).link.as_ref().is_some_and(|l| {
                matches!(l.stop_after, uc100_remote::wire::StopAfter::Armed { .. })
            });
            if armed {
                break;
            }
            assert!(
                deadline.within(&conn(&a).snapshot),
                "never armed: {:?}",
                conn(&a).pi_note
            );
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        let _ = a.update(Message::Disconnect);
        pi_until(&server, 60.0, "the Pi's stop", |s| {
            s.state == Some(State::Idle) && s.program_outcome.as_ref().is_some_and(|o| !o.ok)
        });
        let s = server.snapshot().unwrap();
        assert!(
            s.work_pos[2] > 0.5,
            "the Pi stopped at work Z {}, in the stock",
            s.work_pos[2]
        );
        assert!(
            s.log.iter().any(|l| l.contains("stopped")),
            "{:?}",
            s.log.iter().rev().take(6).collect::<Vec<_>>()
        );
        // Connected again: stopped after a hole, not done.
        let _ = a.update(Message::Connect);
        run_until(&mut a, 10.0, "the outcome", |r| r.running.is_none());
        let (ok, message) = run_of(&a).outcome.clone().unwrap();
        assert!(
            !ok && message.starts_with("Stopped after hole"),
            "{message}"
        );
        assert!(!run_of(&a).done[1]);
        assert!(drill.steps.len() > 1);
    }

    /// A tool run lost on the way to the Pi (the link failed as it
    /// crossed): it never runs and no outcome comes, so after a few seconds
    /// with the link live it is put back, nothing having moved, and Cycle
    /// Start can send it again.
    #[test]
    fn a_tool_run_lost_on_the_way_to_the_pi_is_put_back() {
        use crate::run::Action as R;
        use uc100::controller::State;
        let dir = tempfile::tempdir().unwrap();
        let (mut a, _server) = pi_app(dir.path());
        zeroed(&mut a);
        let _ = a.update(Message::Run(R::Setup(0)));
        answer_skips(&mut a, 0);
        a.control.as_mut().unwrap().lose_next_job = true;
        let _ = a.update(Message::Run(R::CycleStart));
        assert!(run_of(&a).running.is_some());
        let started = std::time::Instant::now();
        run_until(&mut a, 10.0, "the lost tool run put back", |r| {
            r.running.is_none()
        });
        assert!(started.elapsed() >= std::time::Duration::from_secs(3));
        let (ok, message) = run_of(&a).outcome.clone().unwrap();
        assert!(!ok && message.contains("did not reach the Pi"), "{message}");
        assert_eq!(conn(&a).snapshot.state, Some(State::Idle));
        assert!(!run_of(&a).done[0]);
        assert!(problems(&a).is_empty(), "{:?}", problems(&a));
        let _ = a.update(Message::Run(R::CycleStart));
        run_until(&mut a, 60.0, "tool run 1", |r| r.done[0]);
    }

    /// Machine zero on the Pi declares X, Y and Z one after another, each
    /// once the driver has logged the one before: ticked with no pause, as
    /// when the network bunches them, the driver would drop all but the
    /// first.
    #[test]
    fn machine_zero_on_the_pi_declares_every_axis_when_ticked_without_pause() {
        let dir = tempfile::tempdir().unwrap();
        let (mut a, _server) = pi_app(dir.path());
        idle(&mut a);
        let _ = a.update(Message::Machine(crate::control::Action::MachineZero(None)));
        let end = std::time::Instant::now() + std::time::Duration::from_secs(10);
        while !conn(&a).snapshot.referenced[..3].iter().all(|r| *r) {
            let _ = a.update(Message::Tick);
            assert!(
                std::time::Instant::now() < end,
                "not every axis declared: {:?} {:?}",
                conn(&a).snapshot.referenced,
                conn(&a)
                    .snapshot
                    .log
                    .iter()
                    .rev()
                    .take(5)
                    .collect::<Vec<_>>()
            );
        }
        let s = &conn(&a).snapshot;
        assert!(
            s.machine_pos[..3].iter().all(|v| v.abs() < 1e-9),
            "{:?}",
            s.machine_pos
        );
    }

    /// Another paired computer controls the Pi's machine: this one watches,
    /// may not start a tool run, and takes control once the other gives it
    /// up.
    #[test]
    fn a_computer_watching_the_pi_takes_control_when_it_is_free() {
        use crate::run::Action as R;
        let dir = tempfile::tempdir().unwrap();
        let (mut a, server) = pi_app(dir.path());
        let code = uc100_remote::data::Data {
            dir: dir.path().join("pi"),
        }
        .new_code()
        .unwrap();
        let other_token =
            uc100_remote::RemoteController::pair(&server.addr().to_string(), &code, "Workshop PC")
                .unwrap();
        let cfg = conn_profile(dir.path());
        let other =
            uc100_remote::RemoteController::start(cfg, &server.addr().to_string(), other_token);
        let end = std::time::Instant::now() + std::time::Duration::from_secs(10);
        while other.link().state != uc100_remote::LinkState::Controlling {
            assert!(
                std::time::Instant::now() < end,
                "the other computer never got control"
            );
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        let _ = a.update(Message::Connect);
        let mut deadline = Deadline::new(5.);
        while !conn(&a).watching() {
            let _ = a.update(Message::Tick);
            assert!(deadline.within(&conn(&a).snapshot) || conn(&a).snapshot.status.is_none());
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        let _ = a.view();
        assert!(!conn(&a).manual() && !conn(&a).idle());
        // Nothing manual reaches the Pi, and the feed shown is the Pi's.
        let _ = a.update(Message::Machine(crate::control::Action::MachineZero(None)));
        let _ = a.update(Message::Machine(crate::control::Action::FeedOverride(50.)));
        assert!(
            conn(&a)
                .pi_note
                .as_ref()
                .is_some_and(|n| n.contains("Take control")),
            "{:?}",
            conn(&a).pi_note
        );
        for _ in 0..20 {
            let _ = a.update(Message::Tick);
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        let s = server.snapshot().unwrap();
        assert!(
            !s.referenced[0] && s.feed_override == 1.0,
            "{:?} {}",
            s.referenced,
            s.feed_override
        );
        assert_eq!(conn(&a).feed_override, 100.);
        let _ = a.update(Message::Run(R::Setup(0)));
        answer_skips(&mut a, 0);
        assert!(
            problems(&a).iter().any(|p| p.contains("Take control")),
            "{:?}",
            problems(&a)
        );
        other.release_control();
        // As the page shows it: nobody controls, then Take control.
        let end = std::time::Instant::now() + std::time::Duration::from_secs(10);
        while !matches!(
            conn(&a).link.as_ref().map(|l| &l.state),
            Some(uc100_remote::LinkState::Watching { holder: None })
        ) {
            let _ = a.update(Message::Tick);
            assert!(
                std::time::Instant::now() < end,
                "the other never let go: {:?}",
                conn(&a).link.as_ref().map(|l| &l.state)
            );
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        let _ = a.update(Message::PiTakeControl);
        let end = std::time::Instant::now() + std::time::Duration::from_secs(10);
        while !matches!(
            conn(&a).link.as_ref().map(|l| &l.state),
            Some(uc100_remote::LinkState::Controlling)
        ) {
            let _ = a.update(Message::Tick);
            assert!(
                std::time::Instant::now() < end,
                "never took control: {:?}",
                conn(&a).link.as_ref().map(|l| &l.state)
            );
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        other.shutdown();
    }

    /// The profile `pi_app` wrote, as the other computer sends it.
    fn conn_profile(dir: &std::path::Path) -> uc100::config::MachineConfig {
        uc100::config::MachineConfig::load(&dir.join("uc100.toml")).unwrap()
    }

    /// Not paired, Connect says how to pair and connects nothing; the
    /// pairing is kept on this computer (a file beside a test workspace)
    /// and Forget removes it.
    #[test]
    fn connecting_to_the_pi_needs_a_pairing_this_computer_keeps() {
        let dir = tempfile::tempdir().unwrap();
        let mut a = run_app(dir.path());
        let _ = a.update(Message::MachineConnection(crate::control::PI));
        let _ = a.update(Message::Connect);
        assert!(a.control.is_none());
        assert!(a.status.contains("sudo uc100-server pair"), "{}", a.status);
        let _ = a.view();
        let id = a.control_target().unwrap().id.clone();
        let tokens = crate::control::PiTokens::of(&a.state_path, &id);
        assert_eq!(tokens.paired(), Ok(false));
        let token: uc100_remote::Token = format!("7:{}", "ab".repeat(32)).parse().unwrap();
        let _ = a.update(Message::PiPaired(Ok(token.to_string())));
        assert_eq!(tokens.paired(), Ok(true));
        assert_eq!(
            tokens.load().unwrap().unwrap().to_string(),
            token.to_string()
        );
        let _ = a.view();
        let _ = a.update(Message::PiPaired(Err("wrong code".into())));
        assert!(a.status.contains("wrong code"));
        let _ = a.update(Message::PiForget);
        assert_eq!(tokens.paired(), Ok(false));
    }

    /// Stop after step (LIO-275) armed while the Drill drills: the tool run
    /// stops once a hole is done, the tool over the stock, never in a hole;
    /// then Z goes up to the clearance plane and the spindle is off; where it
    /// stopped is kept on disk, and the next hole is the start, checked
    /// again. Pressed twice it is disarmed, and it is offered only while a
    /// tool run runs.
    #[test]
    fn stop_after_step_stops_between_two_holes_with_z_up() {
        use crate::run::Action as R;
        use uc100::controller::State;
        let dir = tempfile::tempdir().unwrap();
        let mut a = run_app(dir.path());
        let _ = a.update(Message::Run(R::StopAfterStep));
        assert!(a.control.as_ref().is_none());
        let drill = drilling(&mut a);
        let p = &run_of(&a).checked().unwrap()[1];
        let plane = crate::post::clearance_plane(&p.blocks) - p.datum[2];
        let _ = a.update(Message::Run(R::StopAfterStep));
        let _ = a.update(Message::Run(R::StopAfterStep));
        assert!(!run_of(&a).stop_after);
        let _ = a.update(Message::Run(R::StopAfterStep));
        assert!(run_of(&a).stop_after);
        let _ = a.view();
        // Where the tool stops: over the stock top (work Z 0).
        let mut deadline = Deadline::new(30.);
        loop {
            let _ = a.update(Message::Tick);
            let s = &conn(&a).snapshot;
            if run_of(&a).running.is_none() && s.state == Some(State::Idle) {
                break;
            }
            assert!(deadline.within(s));
            std::thread::sleep(std::time::Duration::from_millis(5));
        }
        let stopped = conn(&a).snapshot.work_pos[2];
        let run = run_of(&a);
        let (ok, message) = run.outcome.clone().unwrap();
        assert!(
            !ok && message.starts_with("Stopped after hole"),
            "{message}"
        );
        assert!(!run.done[1] && !run.stop_after);
        assert!(
            stopped > 0.5,
            "the tool stopped at work Z {stopped}, in the stock"
        );
        // The journal: the hole done; the next hole the start.
        let path = dir.path().join("uc100");
        let journal = std::fs::read_dir(&path)
            .unwrap()
            .flatten()
            .find(|e| e.file_name().to_string_lossy().ends_with("-journal.json"))
            .map(|e| crate::run::Journal::read(&e.path()).unwrap())
            .expect("the journal on disk");
        let last = journal.step.unwrap();
        assert!(last + 1 < drill.steps.len(), "{last}");
        assert_eq!(
            (journal.op, journal.steps, journal.why.as_str()),
            (1, drill.steps.len(), "Stop after step")
        );
        assert_eq!(journal.fingerprint, drill.fingerprint);
        assert!(
            message.ends_with(&format!("hole {}", last + 1)),
            "{message}"
        );
        // Z up to the clearance plane, the spindle off.
        // (No move when the stop left it there already.)
        tick_until(&mut a, 5.0, "Z up", |s| {
            s.state == Some(State::Idle) && (s.work_pos[2] - plane as f64).abs() < 1e-3
        });
        let s = conn(&a).snapshot.clone();
        assert!(
            (s.work_pos[2] - plane as f64).abs() < 1e-3,
            "{}",
            s.work_pos[2]
        );
        assert_eq!(s.spindle, Some(uc100::gcode::Spindle::Off));
        // The next hole is the start, once the setup is checked again.
        assert!(run_of(&a).programs.is_none() && problems(&a).len() == 1);
        answer_skips(&mut a, 0);
        assert_eq!(run_of(&a).at_step(), Some((1, last + 1)));
        assert_eq!(run_of(&a).open, Some(1));
    }

    /// `run_app`'s Drill fed at 600 mm/min, a few seconds a hole: long
    /// enough to E-stop in it however loaded the test machine is. At FAST's
    /// 30000 mm/min the tool is past it before the E-stop lands (LIO-313).
    fn slow_holes(a: &mut App) {
        let op = &mut a.doc.setups[0].operations[1];
        assert_eq!(op.strategy, Strategy::Drill);
        op.p.insert("feed".into(), "600".into());
    }

    /// An E-stop while a hole is drilled (LIO-275): that hole counts as not
    /// done, the journal keeps the one before it, and it is the start, cut
    /// again from its start.
    #[test]
    fn an_e_stop_mid_step_cuts_that_step_again() {
        use crate::run::Action as R;
        let dir = tempfile::tempdir().unwrap();
        let mut a = run_app(dir.path());
        slow_holes(&mut a);
        let drill = drilling(&mut a);
        assert!(drill.steps.len() >= 2);
        // Into the second hole, before its cutting is done.
        run_until(&mut a, 30.0, "hole 2", |r| {
            let line = None;
            r.step_at(line)
                .is_some_and(|(oi, s, done)| oi == 1 && s == 1 && !done)
        });
        let _ = a.update(Message::MachineEStop);
        run_until(&mut a, 5.0, "the E-stop", |r| r.running.is_none());
        let journal = a.control.as_ref().unwrap().journal().expect("the journal");
        assert_eq!((journal.op, journal.step), (1, Some(0)), "{journal:?}");
        assert!(journal.why.contains("E-stop"), "{}", journal.why);
        assert!(run_of(&a).programs.is_none());
        answer_skips(&mut a, 0);
        assert_eq!(run_of(&a).at_step(), Some((1, 1)));
        // Picked again, as in a new session: the journal picks hole 2, its
        // steps unfolded, and the run bar says so.
        let _ = a.update(Message::Run(R::Setup(0)));
        answer_skips(&mut a, 0);
        assert!(run_of(&a).recheck && run_of(&a).programs.is_none());
        answer_skips(&mut a, 0);
        let run = run_of(&a);
        assert_eq!((run.at_step(), run.open), (Some((1, 1)), Some(1)));
        assert!(run.resumed.is_some());
        let _ = a.update(Message::MachineReset);
        tick_until(&mut a, 3.0, "Idle after Reset", |s| {
            s.state == Some(uc100::controller::State::Idle)
        });
        let (line, _) = crate::ui::run_line(&a, conn(&a));
        assert!(
            line[0].0.starts_with("Start ") && line[0].0.ends_with(" at hole 2"),
            "{line:?}"
        );
        // After the E-stop: the machine position too, before Cycle Start.
        assert!(
            problems(&a)
                .iter()
                .any(|p| p.contains("no machine position")),
            "{:?}",
            problems(&a)
        );
    }

    /// A check answered while the Drill drills waits to be pictured (#167).
    /// The E-stop in hole 2 makes that hole the start, which the setup is
    /// checked again for: the stock of the check before is dropped, not
    /// pictured under the new check's epoch as if it were its own, and the
    /// new check's is pictured once it answers (LIO-313).
    #[test]
    fn a_check_again_after_an_e_stop_pictures_its_own_stock() {
        use crate::run::Action as R;
        use uc100::controller::State;
        let dir = tempfile::tempdir().unwrap();
        let mut a = run_app(dir.path());
        slow_holes(&mut a);
        zeroed(&mut a);
        check_run_pictured(&mut a, dir.path(), 0);
        assert_eq!(run_of(&a).pictures.len(), 2);
        let check = stock_check(&a, 0);
        let _ = a.update(Message::Run(R::Next(1)));
        let _ = a.update(Message::Run(R::KeepZero));
        assert!(problems(&a).is_empty(), "{:?}", problems(&a));
        let _ = a.update(Message::Run(R::CycleStart));
        run_until(&mut a, 30.0, "hole 2", |r| {
            r.step_at(None)
                .is_some_and(|(oi, s, done)| oi == 1 && s == 1 && !done)
        });
        answer_stock(&mut a, dir.path(), check);
        assert!(run_of(&a).pictures.is_empty() && run_of(&a).left.is_some());
        let epoch = run_of(&a).epoch;
        let _ = a.update(Message::MachineEStop);
        run_until(&mut a, 5.0, "the E-stop", |r| r.running.is_none());
        tick_until(&mut a, 2.0, "E-stop", |s| s.state == Some(State::EStop));
        // Checked again, its stock not yet worked out: nothing to picture.
        let run = run_of(&a);
        assert!(
            run.epoch > epoch && run.programs.is_none(),
            "{:?}",
            run.outcome
        );
        assert_eq!((a.picture_job, run.left.is_some()), (None, false));
        let check = stock_check(&a, 0);
        answer_stock(&mut a, dir.path(), check);
        assert_eq!(run_of(&a).at_step(), Some((1, 1)));
        assert_eq!(run_of(&a).pictures.len(), 2);
        assert_eq!(a.picture_job, None);
    }

    /// The Face and the Pocket, one tool run, its Cycle Start sent, and
    /// Stop after step armed once the tool cuts step `s` of operation `oi`:
    /// the stop's journal once the machine is Idle (LIO-311).
    fn stop_after(a: &mut App, oi: usize, s: usize) -> crate::run::Journal {
        use crate::run::Action as R;
        use uc100::controller::State;
        zeroed(a);
        let _ = a.update(Message::Run(R::Setup(0)));
        answer_skips(a, 0);
        assert!(problems(a).is_empty(), "{:?}", problems(a));
        let _ = a.update(Message::Run(R::CycleStart));
        run_until(a, 30.0, "the step", |r| {
            r.step_at(None)
                .is_some_and(|(o, n, done)| (o, n, done) == (oi, s, false))
        });
        let _ = a.update(Message::Run(R::StopAfterStep));
        assert!(run_of(a).stop_after);
        run_until(a, 30.0, "the stop", |r| r.running.is_none());
        tick_until(a, 5.0, "Idle", |s| s.state == Some(State::Idle));
        a.control.as_ref().unwrap().journal().expect("the journal")
    }

    /// Stop after step armed in the Face's last level, the Pocket next in
    /// its tool run (LIO-311): it stops at the Face's end, though the Face's
    /// last move is its rise to the clearance, and not after the Pocket's
    /// first level; the Pocket is the start then.
    #[test]
    fn stop_after_step_armed_in_the_face_stops_at_its_end() {
        let dir = tempfile::tempdir().unwrap();
        let mut a = run_app_of(dir.path(), FAST, &[0, 1]);
        let left = crate::run::check_steps(&a.doc, a.part_mesh().unwrap(), 0, &[], &[]).1;
        let levels = left.steps.iter().find(|s| s.op == 0).unwrap().steps.len();
        let journal = stop_after(&mut a, 0, levels - 1);
        assert_eq!((journal.op, journal.step), (0, Some(levels - 1)));
        let run = run_of(&a);
        let (ok, message) = run.outcome.clone().unwrap();
        assert!(
            !ok && message == format!("Stopped after {}", run.step_label(0, levels - 1)),
            "{message}"
        );
        assert!(!run.done[0]);
        assert_eq!((run.next, run.from, run.at_step()), (0, 1, None));
        // Over the stock top (work Z 0), not in the Pocket.
        let z = conn(&a).snapshot.work_pos[2];
        assert!(z > 0.5, "the tool stopped at work Z {z}");
    }

    /// Stopped after the Pocket's first level, the Face before it in its
    /// tool run (LIO-311): the start at its second level checks, the level
    /// done taken off the stock the Pocket's re-entry descends into, and
    /// runs to the end of the tool run.
    #[test]
    fn a_resume_after_the_pockets_first_level_checks_and_runs() {
        use crate::run::Action as R;
        use uc100::controller::State;
        let dir = tempfile::tempdir().unwrap();
        let mut a = run_app_of(dir.path(), FAST, &[0, 1]);
        let journal = stop_after(&mut a, 1, 0);
        assert_eq!((journal.op, journal.step), (1, Some(0)));
        assert!(run_of(&a).programs.is_none());
        answer_skips(&mut a, 0);
        let run = run_of(&a);
        assert!(run.checked().is_some(), "{:?}", run.programs);
        assert_eq!(run.at_step(), Some((1, 1)));
        let _ = a.update(Message::Run(R::KeepZero));
        let _ = a.update(Message::Run(R::KeepToolZ));
        assert!(problems(&a).is_empty(), "{:?}", problems(&a));
        let _ = a.update(Message::Run(R::CycleStart));
        tick_until(&mut a, 5.0, "the pause over the entry", |s| {
            matches!(s.state, Some(State::Paused(_)))
        });
        let _ = a.update(Message::Run(R::Resume));
        run_until(&mut a, 60.0, "the Pocket's tool run", |r| r.done[0]);
        assert!(run_of(&a).outcome.as_ref().unwrap().0);
    }

    /// Cycle Start runs the operations a run does not skip: with the Pocket
    /// already cut and the Drill's material left, tool run 1 cuts the Face
    /// and the Contour, and the Drill's tool run is skipped whole, with no
    /// tool change for it.
    #[test]
    fn a_tool_run_of_skipped_operations_is_skipped_with_no_tool_change() {
        use crate::run::{Action as R, Skip::*};
        let dir = tempfile::tempdir().unwrap();
        let mut a = ops_app(dir.path());
        zeroed(&mut a);
        let _ = a.update(Message::Run(R::Setup(0)));
        answer_skips(&mut a, 0);
        assert!(skip(&mut a, 1, Some(Cut)) && skip(&mut a, 3, Some(Left)));
        assert_eq!(sent(&a), [vec![0, 2]]);
        assert!(problems(&a).is_empty(), "{:?}", problems(&a));
        let _ = a.update(Message::Run(R::CycleStart));
        let names: Vec<String> = (run_of(&a).running_blocks().unwrap().iter())
            .filter_map(|b| match b {
                crate::post::Block::Start { op, .. } => {
                    Some(run_of(&a).checked().unwrap()[0].ops[*op].name.clone())
                }
                _ => None,
            })
            .collect();
        let ops = &a.doc.setups[0].operations;
        assert_eq!(names, [ops[0].name(), ops[2].name()], "{names:?}");
        run_until(&mut a, 30.0, "tool run 1", |r| r.done[0]);
        assert!(run_of(&a).outcome.as_ref().unwrap().0);
        assert!(run_of(&a).tool_change().is_none());
        assert!(problems(&a).iter().any(|p| p.contains("Every tool run")));
        // What was cut stays cut: the Drill taken back is next, and the
        // Pocket stays skipped. A skip is taken once the machine is Idle,
        // which it is a tick after the tool run's outcome.
        tick_until(&mut a, 5.0, "Idle after tool run 1", |s| {
            s.state == Some(uc100::controller::State::Idle)
        });
        assert!(skip(&mut a, 3, None));
        assert_eq!(sent(&a), [vec![0, 2], vec![3]]);
        assert_eq!(
            (run_of(&a).done.clone(), run_of(&a).next),
            (vec![true, false], 1)
        );
    }

    /// The skips are offered only once the machine is Idle after a tool run:
    /// in the driver's tick between the outcome and Idle (Run, or Stopping
    /// for a stop) the Operations list emits no skip or skip menu and a skip
    /// sent anyway is refused; Idle, Don't skip is there and taken.
    #[test]
    fn skips_are_offered_once_the_machine_is_idle_after_a_tool_run() {
        use crate::run::{Action as R, Skip::*};
        use uc100::controller::State;
        let dir = tempfile::tempdir().unwrap();
        let mut a = ops_app(dir.path());
        zeroed(&mut a);
        let _ = a.update(Message::Run(R::Setup(0)));
        answer_skips(&mut a, 0);
        assert!(skip(&mut a, 1, Some(Cut)) && skip(&mut a, 3, Some(Left)));
        let _ = a.update(Message::Run(R::CycleStart));
        run_until(&mut a, 30.0, "tool run 1", |r| r.done[0]);
        let _ = a.update(Message::Resized(iced::Size::new(1440., 900.)));
        let clicks = |a: &App| {
            crate::ui::probe::clicks(crate::ui::program(a, conn(a)), iced::Size::new(440., 900.))
        };
        let observed = conn(&a).snapshot.state.clone();
        for state in [State::Run, State::Stopping] {
            a.control.as_mut().unwrap().snapshot.state = Some(state.clone());
            let messages = clicks(&a);
            assert!(
                !messages
                    .iter()
                    .any(|m| matches!(m, Message::Run(R::Skip(..) | R::More(Some(_))))),
                "a skip offered before Idle, {state:?}: {messages:?}"
            );
            assert!(!skip(&mut a, 3, None));
            assert_eq!(run_of(&a).skips, [(1, Cut), (3, Left)]);
        }
        a.control.as_mut().unwrap().snapshot.state = observed;
        tick_until(&mut a, 5.0, "Idle after tool run 1", |s| {
            s.state == Some(State::Idle)
        });
        let message = (clicks(&a).into_iter())
            .find(|m| matches!(m, Message::Run(R::Skip(3, None))))
            .expect("Don't skip offered for the Drill once Idle");
        let _ = a.update(message);
        assert!(
            run_of(&a).programs.is_none(),
            "the click checks the setup again"
        );
        answer_skips(&mut a, 0);
        assert_eq!(sent(&a), [vec![0, 2], vec![3]]);
    }

    /// The Tool runs panel shows each operation with a picture of the stock
    /// it leaves, each different, and where it stands: the first marked
    /// next, then the one being cut and those done before it while its tool
    /// run cuts, all done after (#229).
    #[test]
    fn each_operation_of_a_run_is_pictured_with_where_it_stands() {
        use crate::run::{Action as R, Stage::*};
        use uc100::controller::State;
        let dir = tempfile::tempdir().unwrap();
        let mut a = ops_app(dir.path());
        zeroed(&mut a);
        check_run_pictured(&mut a, dir.path(), 0);
        let run = run_of(&a);
        let programs = run.checked().unwrap();
        assert_eq!(
            programs
                .iter()
                .map(|p| p.indexes.clone())
                .collect::<Vec<_>>(),
            vec![vec![0, 1, 2], vec![3]]
        );
        let pixels = |op| {
            let Some(iced::widget::image::Handle::Rgba { pixels, .. }) = run_of(&a).picture(op)
            else {
                panic!(
                    "no picture of operation {op}: {:?}",
                    run_of(&a).pictures.len()
                )
            };
            pixels.clone()
        };
        let drawn = run_of(&a).pictures.clone();
        let pictures = move |_: &App| drawn.clone();
        let pixels: Vec<_> = (0..4).map(pixels).collect();
        for k in 1..4 {
            assert_ne!(pixels[k - 1], pixels[k], "operation {k}");
        }
        let line = |a: &App| conn(a).snapshot.current_line;
        let stages = |a: &App, i| run_of(a).stages(i, line(a));
        assert_eq!(stages(&a, 0), [Next, ToCome, ToCome]);
        assert_eq!(stages(&a, 1), [ToCome]);
        let _ = a.view();
        assert!(problems(&a).is_empty(), "{:?}", problems(&a));
        let check = stock_check(&a, 0);
        let _ = a.update(Message::Run(R::CycleStart));
        tick_until(&mut a, 2.0, "the job", |s| s.state == Some(State::Run));
        let mut deadline = Deadline::new(30.);
        while stages(&a, 0) != [Done, Cutting, ToCome] {
            let _ = a.update(Message::Tick);
            assert!(deadline.within(&conn(&a).snapshot), "{:?}", stages(&a, 0));
            std::thread::sleep(std::time::Duration::from_millis(5));
        }
        // The pictures stay through the run.
        assert_eq!(run_of(&a).pictures.len(), 4);
        // A check answered while the machine cuts is not pictured then: the
        // meshing would compete with the driver feeding it (#167). Cycle
        // Start waits for its pictures.
        let busy = Some("The stock after each operation is still being pictured: wait a moment.");
        answer_stock(&mut a, dir.path(), check);
        assert!(run_of(&a).pictures.is_empty() && run_of(&a).left.is_some());
        assert_eq!(a.planning_busy(), busy);
        // Nor by the Tick, until tool run 1 ends; then the Tick pictures it.
        let epoch = run_of(&a).epoch;
        let mut deadline = Deadline::new(60.);
        while a.picture_job.is_none() {
            let _ = a.update(Message::Tick);
            assert!(
                run_of(&a).running.is_none() || run_of(&a).left.is_some(),
                "pictured while tool run 1 cuts"
            );
            assert!(deadline.within(&conn(&a).snapshot), "{:?}", stages(&a, 0));
            std::thread::sleep(std::time::Duration::from_millis(5));
        }
        assert!(run_of(&a).outcome.as_ref().is_some_and(|o| o.0));
        assert_eq!(stages(&a, 0), [Done, Done, Done]);
        assert_eq!(stages(&a, 1), [Next]);
        assert!(a.picture_job == Some(epoch) && run_of(&a).left.is_none());
        assert_eq!(a.planning_busy(), busy);
        let _ = a.update(Message::RunPictures(epoch, pictures(&a)));
        assert_eq!(run_of(&a).pictures.len(), 4);
        assert_eq!(a.planning_busy(), None);
    }

    /// The Run strip estimates the setup, and while a tool run cuts counts
    /// down what is left of it, its operation and the setup: the estimate
    /// is the simulated machine's own time for the tool run, as its planner
    /// moves it.
    #[test]
    fn the_run_estimates_the_setup_and_counts_down_while_it_cuts() {
        use crate::run::Action as R;
        use uc100::controller::State;
        let dir = tempfile::tempdir().unwrap();
        let mut a = ops_app(dir.path());
        zeroed(&mut a);
        check_run(&mut a, 0);
        let s = conn(&a).snapshot.clone();
        let run = run_of(&a);
        let times = run.times.clone().expect("the check is timed");
        let total = run.setup_time().unwrap();
        let first = times.run(0, 0).unwrap();
        assert!(first > 1. && total > first, "{first} {total}");
        let left = run.left(&s).unwrap();
        assert_eq!((left.op, left.run, left.setup), (None, first, total));
        let ops = run.op_times(0).unwrap();
        assert_eq!(ops.len(), 3);
        assert!(
            (ops.iter().sum::<f32>() - first).abs() < 1e-3,
            "{ops:?} {first}"
        );
        // Started at the Pocket, its card's time has the safe start too: the
        // cards from there add up to what is left of the tool run.
        let _ = a.update(Message::Run(R::From(0, 1)));
        let from = run_of(&a).op_times(0).unwrap();
        let left = run_of(&a).left(&s).unwrap();
        assert_eq!(from[0], ops[0]);
        assert!(
            (from[1] + from[2] - left.run).abs() < 1e-3,
            "{from:?} {left:?}"
        );
        let _ = a.update(Message::Run(R::From(0, 0)));
        assert_eq!(run_of(&a).op_times(0).unwrap(), ops);
        let started = std::time::Instant::now();
        let _ = a.update(Message::Run(R::CycleStart));
        tick_until(&mut a, 2.0, "the job", |s| s.state == Some(State::Run));
        let mut seen = vec![];
        let mut deadline = Deadline::new(60.);
        while !run_of(&a).done[0] {
            let _ = a.update(Message::Tick);
            let _ = a.view();
            if let Some(l) = run_of(&a).left(&conn(&a).snapshot)
                && l.op.is_some()
            {
                seen.push(l);
            }
            assert!(deadline.within(&conn(&a).snapshot));
            std::thread::sleep(std::time::Duration::from_millis(20));
        }
        let took = started.elapsed().as_secs_f32();
        // The machine's time, and the estimate's, within a tenth and the
        // ticks' lag.
        assert!(
            (took - first).abs() < 0.1 * first + 0.5,
            "took {took} s, estimated {first} s"
        );
        // It counts down: what is left of the tool run and of the setup only
        // falls, each operation's left is part of it, and its last is near 0.
        assert!(seen.len() > 10, "{}", seen.len());
        for w in seen.windows(2) {
            assert!(w[1].run <= w[0].run + 0.05, "{:?}", w);
            assert!((w[1].setup - w[1].run - (total - first)).abs() < 1e-3);
        }
        for l in &seen {
            let (_, op_left, op_all) = l.op.unwrap();
            assert!(op_left <= op_all + 1e-3 && op_left <= l.run + 1e-3, "{l:?}");
        }
        assert!(
            seen[0].run > 0.8 * first && seen.last().unwrap().run < 1.,
            "{:?}",
            seen.last()
        );
        let ops: Vec<usize> = seen.iter().map(|l| l.op.unwrap().0).collect();
        assert!(
            ops.windows(2).all(|w| w[0] <= w[1]) && ops.contains(&1),
            "{ops:?}"
        );
        // Done: the next tool run, and the setup's last, is what is left.
        tick_until(&mut a, 2.0, "Idle", |s| s.state == Some(State::Idle));
        let l = run_of(&a).left(&conn(&a).snapshot).unwrap();
        assert_eq!((l.op, l.run, l.setup), (None, total - first, total - first));
    }

    /// Renders the Control page's Tool runs panel to PNGs in
    /// `$AXIS_RENDER_DIR` (default /tmp/op-cards): before the run, while the
    /// Pocket of tool run 1 is cut, and at the tool change after it. Not a
    /// check: run it with --ignored.
    #[test]
    #[ignore]
    fn render_the_operation_cards() {
        use crate::run::{Action as R, Stage::*};
        use uc100::controller::State;
        let out = std::path::PathBuf::from(
            std::env::var("AXIS_RENDER_DIR").unwrap_or("/tmp/op-cards".into()),
        );
        std::fs::create_dir_all(&out).unwrap();
        let size = iced::Size::new(1600., 1500.);
        let dir = tempfile::tempdir().unwrap();
        let mut a = ops_app(dir.path());
        zeroed(&mut a);
        check_run_pictured(&mut a, dir.path(), 0);
        let _ = a.view();
        render_png(&a, size, &out.join("1-before-the-run.png"));
        let _ = a.update(Message::Run(R::CycleStart));
        tick_until(&mut a, 2.0, "the job", |s| s.state == Some(State::Run));
        let mut deadline = Deadline::new(30.);
        while run_of(&a).stages(0, conn(&a).snapshot.current_line) != [Done, Cutting, ToCome] {
            let _ = a.update(Message::Tick);
            assert!(deadline.within(&conn(&a).snapshot));
            std::thread::sleep(std::time::Duration::from_millis(5));
        }
        let _ = a.view();
        render_png(&a, size, &out.join("2-cutting-the-pocket.png"));
        run_until(&mut a, 30.0, "tool run 1", |r| r.done[0]);
        tick_until(&mut a, 2.0, "Idle", |s| s.state == Some(State::Idle));
        let _ = a.view();
        render_png(&a, size, &out.join("3-tool-change.png"));
    }

    /// The jog buttons' places on the Control page at 1440 × 790, by the
    /// direction each jogs: where a press gives `JogPress`.
    fn jog_pad(a: &App) -> Vec<(iced::Point, usize, bool)> {
        let window = iced::Size::new(1440., 790.);
        let area = iced::Rectangle::new(
            iced::Point::ORIGIN,
            iced::Size::new(crate::ui::Fit::of(a).hands() + 20., window.height),
        );
        crate::ui::probe::presses(a.view(), window, area, 6.)
            .into_iter()
            .filter_map(|(at, m)| match m {
                Message::Machine(crate::control::Action::JogPress(axis, negative)) => {
                    Some((at, axis, negative))
                }
                _ => None,
            })
            .collect()
    }

    /// A step's hover card leaves the steps after it to be clicked: with
    /// Hole 1's card open, each hole below still picks itself (LIO-312).
    #[test]
    fn a_steps_hover_card_leaves_the_steps_below_it_clickable() {
        use crate::run::Action as R;
        let dir = tempfile::tempdir().unwrap();
        let mut a = ops_app(dir.path());
        zeroed(&mut a);
        let _ = a.update(Message::Run(R::Setup(0)));
        answer_skips(&mut a, 0);
        let (oi, n) = (run_of(&a).steps.iter())
            .find(|s| s.hole)
            .map(|s| (s.op, s.steps.len()))
            .expect("the Drilling's holes");
        assert!(n > 2, "{n}");
        let _ = a.update(Message::Run(R::Steps(Some(oi))));
        let window = iced::Size::new(1440., 790.);
        let _ = a.update(Message::Resized(window));
        let column = iced::Rectangle::new(
            iced::Point::new(window.width - 420., 0.),
            iced::Size::new(420., window.height),
        );
        // The middle of each step row, where a press picks it.
        let presses = crate::ui::probe::presses(a.view(), window, column, 4.);
        let rows: Vec<iced::Point> = (0..n)
            .map(|s| {
                let at: Vec<_> = (presses.iter())
                    .filter(|(_, m)| matches!(m, Message::Run(R::PickStep(o, t)) if (*o, *t) == (oi, s)))
                    .map(|(at, _)| *at)
                    .collect();
                assert!(!at.is_empty(), "step {s} of {oi} has no place to press: {presses:?}");
                at[at.len() / 2]
            })
            .collect();
        for (s, &at) in rows.iter().enumerate().skip(1) {
            let pressed = crate::ui::probe::presses_after(
                a.view(),
                window,
                Some(rows[0]),
                iced::Rectangle::new(at, iced::Size::new(1., 1.)),
                1.,
            );
            assert!(
                matches!(pressed[..], [(_, Message::Run(R::PickStep(o, t)))] if (o, t) == (oi, s)),
                "step {s} under Hole 1's card: {pressed:?}"
            );
        }
    }

    /// Nothing around the jog pad moves while the machine jogs: leaving a
    /// jog button stops the jog, so a button that moved from under the
    /// pointer would stop it (LIO-274). The page itself never scrolls at
    /// 1440 × 790: only the lists in it do, inside their own area.
    #[test]
    fn the_jog_pad_stays_put_while_the_machine_jogs_and_the_page_does_not_scroll() {
        use uc100::controller::State;
        let dir = tempfile::tempdir().unwrap();
        let mut a = ops_app(dir.path());
        zeroed(&mut a);
        check_run(&mut a, 0);
        let still = jog_pad(&a);
        for axis in 0..3 {
            for negative in [false, true] {
                assert!(
                    still.iter().any(|&(_, x, n)| (x, n) == (axis, negative)),
                    "no jog button for axis {axis} {negative}"
                );
            }
        }
        let _ = a.update(Message::Machine(crate::control::Action::JogPress(1, false)));
        tick_until(&mut a, 3.0, "jogging", |s| s.state == Some(State::Jog));
        let moving = jog_pad(&a);
        let _ = a.update(Message::Machine(crate::control::Action::JogRelease));
        assert_eq!(still, moving);
        // Every scrollable is inside the page under the run bar, none of it
        // the page's: the page has no scrollbar.
        let window = iced::Size::new(1440., 790.);
        let fit = crate::ui::Fit::of(&a);
        let top = fit.machine_bar() + fit.run_bar();
        for tab in [
            crate::ui::ControlTab::Job,
            crate::ui::ControlTab::WorkZero,
            crate::ui::ControlTab::Probe,
            crate::ui::ControlTab::Mdi,
            crate::ui::ControlTab::Machine,
        ] {
            let _ = a.update(Message::ControlTab(tab));
            for (id, at) in crate::ui::probe::scrollables(a.view(), window) {
                assert!(
                    at.y >= top && at.width < window.width - fit.hands(),
                    "{tab:?}: {id:?} at {at:?} scrolls the page"
                );
            }
        }
    }

    /// The jog keys jog only while the jog pad is on screen: not in the
    /// Controller configuration view nor on another page (LIO-273). The two
    /// Stops say which they stop, and without a probe input the Probe tab is
    /// one line and the way to the profile.
    #[test]
    fn the_keys_jog_only_with_the_pad_on_screen_and_the_stops_say_what_they_stop() {
        let dir = tempfile::tempdir().unwrap();
        let mut a = run_app(dir.path());
        idle(&mut a);
        let key = |a: &mut App| {
            let _ = a.update(Message::JogKey(1, false, false));
            let _ = a.update(Message::JogKeyChecked(1, false, false));
            let held = conn(a).held();
            let _ = a.update(Message::JogKeyUp);
            held
        };
        assert!(a.jog_pad_shown());
        assert_eq!(key(&mut a), Some((1, false)));
        let _ = a.update(Message::ControlSetup(true));
        assert!(!a.jog_pad_shown());
        assert_eq!(key(&mut a), None);
        let _ = a.update(Message::ControlSetup(false));
        a.page = Page::Home;
        assert!(!a.jog_pad_shown());
        assert_eq!(key(&mut a), None);
        a.page = Page::Control;
        let texts = page_texts(&a);
        let has = |t: &str| texts.iter().any(|x| x == t);
        assert!(
            has("Stop now") && has("Spindle off") && !has("Stop"),
            "{texts:?}"
        );
        let _ = a.update(Message::ControlTab(crate::ui::ControlTab::Probe));
        let texts = page_texts(&a);
        assert!(
            texts.iter().any(|t| t.contains("has no probe input"))
                && !texts.iter().any(|t| t == "Probe Z"),
            "{texts:?}"
        );
    }

    /// Renders the Control page in each state and tab to
    /// `$AXIS_RENDER_DIR` (default /tmp/control-page), a folder for each
    /// window size: 1440 × 900, 1440 × 790 (the usable window of a 13"
    /// laptop), 1280 × 690 (the same with larger text), 1120 × 720 and
    /// 1120 × 690 (the least window). Not connected, E-stop, idle, before the run, each tab,
    /// cutting, holding, the tool change, and a machine with A; once more
    /// at 1920 × 1080. Not a check: run it with --ignored.
    #[test]
    #[ignore]
    fn render_the_control_page() {
        use crate::run::{Action as R, Stage::*};
        use crate::ui::ControlTab as T;
        use uc100::controller::State;
        let out = std::path::PathBuf::from(
            std::env::var("AXIS_RENDER_DIR").unwrap_or("/tmp/control-page".into()),
        );
        let shot = |a: &mut App, name: &str| {
            for (w, h) in [
                (1440., 900.),
                (1440., 790.),
                (1280., 690.),
                (1120., 720.),
                (1120., 690.),
            ] {
                let size = iced::Size::new(w, h);
                let _ = a.update(Message::Resized(size));
                let dir = out.join(format!("{w}x{h}"));
                std::fs::create_dir_all(&dir).unwrap();
                render_png(a, size, &dir.join(format!("{name}.png")));
            }
        };
        let dir = tempfile::tempdir().unwrap();
        let mut a = ops_app(dir.path());
        let _ = a.view();
        shot(&mut a, "00-not-connected");
        let _ = a.update(Message::Connect);
        tick_until(&mut a, 3.0, "E-stop after connecting", |s| {
            s.state == Some(State::EStop)
        });
        shot(&mut a, "01-e-stop");
        let _ = a.update(Message::MachineReset);
        tick_until(&mut a, 3.0, "Idle after Reset", |s| {
            s.state == Some(State::Idle)
        });
        shot(&mut a, "02-connected-idle");
        zero(&mut a);
        check_run_pictured(&mut a, dir.path(), 0);
        shot(&mut a, "03-before-the-run");
        move_to_shot(&mut a, &shot, "03-move-to", &["62", "42", "2"]);
        for (tab, name) in [
            (T::WorkZero, "work-zero"),
            (T::Probe, "probe"),
            (T::Mdi, "mdi"),
            (T::Machine, "machine"),
        ] {
            let _ = a.update(Message::ControlTab(tab));
            shot(&mut a, &format!("04-tab-{name}"));
        }
        let _ = a.update(Message::ControlView(crate::ui::JobView::Machine));
        let _ = a.update(Message::ControlTab(T::Job));
        shot(&mut a, "04-tab-job-machine");
        let _ = a.update(Message::ControlView(crate::ui::JobView::Stock));
        // The Contour skipped as cut, the Drill with its material left (its
        // tool run with it), and the Face's skips open: the Pocket cuts
        // beneath it, so its material cannot be left.
        assert!(skip(&mut a, 2, Some(crate::run::Skip::Cut)));
        assert!(skip(&mut a, 3, Some(crate::run::Skip::Left)));
        assert!(run_of(&a).beneath.iter().any(|b| b.0 == 0));
        let _ = a.update(Message::Run(R::More(Some(0))));
        shot(&mut a, "04-skips");
        let _ = a.update(Message::Run(R::More(Some(1))));
        shot(&mut a, "04-skips-pocket");
        let _ = a.update(Message::Run(R::More(None)));
        assert!(skip(&mut a, 2, None) && skip(&mut a, 3, None));
        answer_with_stock(&mut a, dir.path(), 0);
        // The step list (LIO-275): the operation with the most steps
        // unfolded, then a range of them picked by Shift-click.
        let most = (run_of(&a).steps.iter())
            .max_by_key(|s| s.steps.len())
            .map(|s| (s.op, s.steps.len()))
            .unwrap();
        assert!(most.1 > 1, "{most:?}");
        let _ = a.update(Message::Run(R::Steps(Some(most.0))));
        shot(&mut a, "04-steps");
        let _ = a.update(Message::Run(R::PickStep(most.0, 1)));
        let _ = a.update(Message::Shift(true));
        let _ = a.update(Message::Run(R::PickStep(most.0, (most.1 - 1).min(3))));
        let _ = a.update(Message::Shift(false));
        assert_eq!(run_of(&a).picked, Some((most.0, 1, (most.1 - 1).min(3))));
        shot(&mut a, "04-steps-picked");
        // A start at the first picked: its checks in the Start at a step tab.
        let _ = a.update(Message::Run(R::StartStep));
        answer_skips(&mut a, 0);
        assert_eq!(run_of(&a).at_step(), Some((most.0, 1)));
        let _ = a.update(Message::ControlPhaseTab(T::Start, false));
        shot(&mut a, "04-start-at-step");
        let _ = a.update(Message::Run(R::Next(0)));
        answer_with_stock(&mut a, dir.path(), 0);
        let _ = a.update(Message::ControlTab(T::Job));
        let _ = a.update(Message::Run(R::Steps(None)));
        let _ = a.update(Message::Run(R::CycleStart));
        tick_until(&mut a, 2.0, "the job", |s| s.state == Some(State::Run));
        let mut deadline = Deadline::new(30.);
        while run_of(&a).stages(0, conn(&a).snapshot.current_line) != [Done, Cutting, ToCome] {
            let _ = a.update(Message::Tick);
            assert!(deadline.within(&conn(&a).snapshot));
            std::thread::sleep(std::time::Duration::from_millis(5));
        }
        // Held first: the job runs on while the pictures are drawn.
        let _ = a.update(Message::Run(R::Hold));
        tick_until(&mut a, 3.0, "Hold", |s| s.state == Some(State::Hold));
        shot(&mut a, "05-holding");
        let _ = a.update(Message::Run(R::Resume));
        tick_until(&mut a, 3.0, "Run", |s| s.state == Some(State::Run));
        shot(&mut a, "05-cutting");
        // Stop after step armed while it cuts (LIO-275), then disarmed: no
        // tick passes between, so it stops nothing.
        let _ = a.update(Message::Run(R::StopAfterStep));
        assert!(run_of(&a).stop_after);
        shot(&mut a, "05-stop-after-step");
        let _ = a.update(Message::Run(R::StopAfterStep));
        let size = iced::Size::new(1920., 1080.);
        let _ = a.update(Message::Resized(size));
        render_png(&a, size, &out.join("05-cutting-1920x1080.png"));
        run_until(&mut a, 30.0, "tool run 1", |r| r.done[0]);
        tick_until(&mut a, 2.0, "Idle", |s| s.state == Some(State::Idle));
        // The tick's phase change opens the tab once no field has the focus.
        let _ = a.update(Message::ControlPhaseTab(T::ToolChange, false));
        shot(&mut a, "06-tool-change");
        // Z set from the reference: check 4 done, Cycle Start next (LIO-312).
        let _ = a.update(Message::Run(R::RecordReference));
        let _ = a.update(Message::Run(R::ZFromReference));
        run_until(&mut a, 2.0, "Set Z from reference", |r| r.touched);
        shot(&mut a, "06-tool-change-z-set");
        // Resume (LIO-275): where a run stopped, after hole 2 of the Drill,
        // kept in the journal; the setup picked again, as in a new session.
        a.control.as_mut().unwrap().run.as_mut().unwrap().stopped = Some(crate::run::Stopped {
            op: 3,
            last: Some(1),
            up: None,
            why: "Stop after step".into(),
        });
        let _ = a.update(Message::Tick);
        let _ = a.update(Message::Run(R::Setup(0)));
        answer_with_stock(&mut a, dir.path(), 0);
        answer_skips(&mut a, 0);
        assert_eq!(run_of(&a).at_step(), Some((3, 2)));
        let _ = a.update(Message::ControlPhaseTab(T::Start, false));
        shot(&mut a, "08-resume");
        let _ = a.update(Message::Disconnect);
        // A machine with the rotary unit: A in the position, jog and tabs.
        let dir = tempfile::tempdir().unwrap();
        let mut a = App::from_workspace(dir.path().join("workspace.json"), None);
        let mut m = crate::control::rotary_machine(dir.path()).unwrap();
        let profile = dir.path().join("rotary-probed.toml");
        std::fs::write(&profile, crate::control::tests::ROTARY_PROBED).unwrap();
        m.p.insert("uc100_profile".into(), profile.display().to_string());
        m.p.insert("uc100_connection".into(), "Simulated".into());
        a.doc.machines.push(m);
        a.page = Page::Control;
        idle(&mut a);
        shot(&mut a, "07-rotary-idle");
        for (tab, name) in [
            (T::WorkZero, "work-zero"),
            (T::Probe, "probe"),
            (T::Rotary, "rotary"),
            (T::Mdi, "mdi"),
            (T::Machine, "machine"),
        ] {
            let _ = a.update(Message::ControlTab(tab));
            shot(&mut a, &format!("07-rotary-tab-{name}"));
        }
        let _ = a.update(Message::ControlTab(T::Job));
        let _ = a.update(Message::Machine(crate::control::Action::MachineZero(None)));
        tick_until(&mut a, 3.0, "machine zero", |s| {
            s.referenced[..4].iter().all(|r| *r)
        });
        move_to_shot(&mut a, &shot, "07-rotary-move-to", &["62", "42", "2", "90"]);
    }

    /// `shot` of the Control page with Move to open and `targets` typed
    /// (X, Y, Z, A), then Move to closed with the fields emptied.
    fn move_to_shot(a: &mut App, shot: &dyn Fn(&mut App, &str), name: &str, targets: &[&str]) {
        use crate::control::Action;
        let _ = a.update(Message::Machine(Action::MoveTo(true)));
        for (axis, v) in targets.iter().enumerate() {
            let _ = a.update(Message::Machine(Action::TargetText(axis, v.to_string())));
        }
        shot(a, name);
        for axis in 0..targets.len() {
            let _ = a.update(Message::Machine(Action::TargetText(axis, String::new())));
        }
        let _ = a.update(Message::Machine(Action::MoveTo(false)));
    }

