    #[test]
    fn the_control_page_renders_in_every_state() {
        use uc100::controller::State;
        let dir = tempfile::tempdir().unwrap();
        let mut empty = App::from_workspace(dir.path().join("empty.json"), None);
        empty.page = Page::Control;
        let _view = empty.view();
        let mut a = uc100_app(dir.path());
        a.page = Page::Control;
        let _ = a.view();
        let _ = a.update(Message::Connect);
        let _ = a.view();
        tick_until(&mut a, 3.0, "E-stop after connecting", |s| {
            s.state == Some(State::EStop)
        });
        let _ = a.view();
        let _ = a.update(Message::MachineReset);
        tick_until(&mut a, 3.0, "Idle after Reset", |s| {
            s.state == Some(State::Idle)
        });
        for page in [Page::Home, Page::Machines, Page::Control] {
            a.page = page;
            let _ = a.view();
        }
        // The connected machine's UC100 fields are locked in the wizard.
        let id = a.doc.machines[0].id.clone();
        let _ = a.update(Message::EditMachine(id));
        let _ = a.update(Message::WizardStep(3));
        let _ = a.view();
        let _ = a.update(Message::Disconnect);
        // A JY5800-like machine before and after machine zero, and one with switches.
        for profile in [LIMITED, SWITCHED] {
            let dir = tempfile::tempdir().unwrap();
            let mut a = profile_app(dir.path(), profile);
            a.page = Page::Control;
            idle(&mut a);
            let _ = a.view();
            // An axis with a home switch is referenced by homing only.
            let zero = if profile == SWITCHED {
                crate::control::Action::Home
            } else {
                crate::control::Action::MachineZero(None)
            };
            let _ = a.update(Message::Machine(zero));
            // Homing marks its last axis referenced two driver loops before
            // it is back in Idle, and a jog pressed while the driver still
            // reports Homing is rightly dropped (#9).
            tick_until(&mut a, 10.0, "X, Y and Z set, Idle", |s| {
                s.state == Some(State::Idle) && s.referenced[..3].iter().all(|r| *r)
            });
            let _ = a.update(Message::Machine(crate::control::Action::Rpm("abc".into())));
            let _ = a.update(Message::Machine(crate::control::Action::MdiText(
                "G0 X1".into(),
            )));
            let _ = a.view();
            let _ = a.update(Message::Machine(crate::control::Action::JogPress(1, false)));
            tick_until(&mut a, 3.0, "jogging", |s| {
                s.state == Some(uc100::controller::State::Jog)
            });
            let _ = a.view();
            let _ = a.update(Message::Machine(crate::control::Action::JogRelease));
        }
    }

    /// On a screen too short for the least window's height the window opens
    /// as short as the screen leaves it (`least_window`), and there every
    /// page, the connected Control page with and without A among them,
    /// keeps the status bar inside the window and lays out nothing past its
    /// bottom but what scrolls (LIO-315).
    #[test]
    fn every_page_fits_a_window_a_short_screen_high() {
        // 1366 × 768 at 125%, 1920 × 1080 at 175%, 1600 × 900 at 150% and
        // 1920 × 1080 at 150%.
        let screens = [(1093., 614.), (1097., 617.), (1067., 600.), (1280., 720.)]
            .map(|(w, h): (f32, f32)| iced::Size::new(w, h));
        // What does not hold, every page's at once.
        let holds = |a: &mut App, what: &str| {
            let mut wrong = Vec::new();
            for screen in screens {
                let size = crate::opening_window(screen).unwrap();
                let least = crate::least_window(screen).unwrap();
                assert_eq!(size.height, least.height, "{screen:?}");
                // Each text's height with room to spare, at the same fit
                // (`ui::Fit`: short under 860).
                let roomy = iced::Size::new(size.width, 859.);
                let _ = a.update(Message::Resized(roomy));
                let mut natural = std::collections::HashMap::new();
                for (t, b) in laid_out(a, roomy).texts {
                    let h = natural.entry(t).or_insert(b.height);
                    *h = h.min(b.height);
                }
                let _ = a.update(Message::Resized(size));
                let laid = laid_out(a, size);
                let words = (laid.texts.iter())
                    .find(|(t, _)| t.starts_with("mm  |"))
                    .unwrap_or_else(|| panic!("{what} at {size:?}: no status bar"))
                    .1;
                if words.y + words.height > size.height + 0.5 {
                    wrong.push(format!("{what} at {size:?}: the status bar at {words:?}"));
                }
                let within = |b: &iced::Rectangle, c: &iced::Rectangle| {
                    b.x >= c.x - 0.5
                        && b.y >= c.y - 0.5
                        && b.x + b.width <= c.x + c.width + 0.5
                        && b.y + b.height <= c.y + c.height + 0.5
                };
                // The status bar: the window wide, round its words.
                let bar = (laid.boxes.iter())
                    .filter(|b| b.width >= size.width - 0.5 && within(&words, b))
                    .min_by(|p, q| p.height.total_cmp(&q.height))
                    .unwrap();
                // Nothing over it but what holds it, or scrolls: a card
                // pushed down, or squeezed so that its words run out of it,
                // is.
                let over = |b: &iced::Rectangle| {
                    b.y + b.height > bar.y + 0.5
                        && !within(&words, b)
                        && !within(b, bar)
                        && !(laid.scrolls.iter()).any(|(_, c)| within(b, c))
                };
                let boxes: Vec<_> = laid.boxes.iter().filter(|b| over(b)).collect();
                let texts: Vec<_> = laid.texts.iter().filter(|(_, b)| over(b)).collect();
                if !boxes.is_empty() || !texts.is_empty() {
                    wrong.push(format!(
                        "{what} at {size:?}: over the status bar at {bar:?}: {boxes:?} {texts:?}"
                    ));
                }
                // Nor squeezed: a column out of room lays out what does not
                // fit flat, a button's words among it.
                let flat: Vec<_> = (laid.texts.iter())
                    .filter(|(t, b)| natural.get(t).is_some_and(|h| b.height < h - 0.5))
                    .collect();
                if !flat.is_empty() {
                    wrong.push(format!("{what} at {size:?}: squeezed {flat:?}"));
                }
            }
            wrong
        };
        let mut wrong = Vec::new();
        let dir = tempfile::tempdir().unwrap();
        let mut a = run_app_on(dir.path(), FAST);
        for page in [
            Page::Home,
            Page::Work,
            Page::Machines,
            Page::Tools,
            Page::Materials,
            Page::Workholding,
            Page::Post,
            Page::Control,
        ] {
            a.page = page;
            wrong.extend(holds(&mut a, &format!("{page:?}")));
        }
        idle(&mut a);
        wrong.extend(holds(&mut a, "Control, connected"));
        let _ = a.update(Message::Disconnect);
        let dir = tempfile::tempdir().unwrap();
        let mut a = run_app_on(dir.path(), &format!("{FAST}{A_AXIS}"));
        idle(&mut a);
        wrong.extend(holds(&mut a, "Control with A, connected"));
        assert!(wrong.is_empty(), "{}", wrong.join("\n"));
        // The Control page's left column scrolls only where its cards do
        // not fit: on the short screen, not from the least window up.
        for (size, scrolls) in [
            (iced::Size::new(1093., 536.), true),
            (crate::MIN_WINDOW, false),
            (iced::Size::new(1440., 790.), false),
        ] {
            let _ = a.update(Message::Resized(size));
            let laid = laid_out(&a, size);
            let feed = (laid.texts.iter())
                .find(|(t, _)| t.starts_with("Feed now"))
                .unwrap()
                .1;
            assert_eq!(
                (laid.scrolls.iter()).any(|(_, c)| c.contains(feed.center())),
                scrolls,
                "{size:?}"
            );
        }
        let _ = a.update(Message::Disconnect);
    }

    /// The Home page's scroll bar, there only in a window too short for the
    /// page, takes its own room beside the "Continue where you left off"
    /// card rather than being drawn over its edge; where the page fits there
    /// is no bar and the page is centred in the whole width (LIO-327).
    #[test]
    fn the_home_pages_scroll_bar_is_beside_its_card() {
        let dir = tempfile::tempdir().unwrap();
        let mut a = App::from_workspace(dir.path().join("w.json"), None);
        a.page = Page::Home;
        for (size, scrolls) in [
            (iced::Size::new(1093., 536.), true),
            (iced::Size::new(1440., 900.), false),
            (iced::Size::new(1920., 1040.), false),
        ] {
            let _ = a.update(Message::Resized(size));
            let laid = laid_out(&a, size);
            let heading = (laid.texts.iter())
                .find(|(t, _)| t == "Continue where you left off")
                .unwrap()
                .1;
            let card = *(laid.boxes.iter())
                .filter(|b| (b.width - 380.).abs() < 0.5 && b.contains(heading.center()))
                .min_by(|p, q| p.height.total_cmp(&q.height))
                .unwrap_or_else(|| panic!("{size:?}: no card"));
            let (shown, content) = *(laid.scrolls.iter())
                .find(|(b, _)| b.contains(card.center()))
                .unwrap_or_else(|| panic!("{size:?}: the page does not scroll"));
            assert_eq!(content.height > shown.height + 0.5, scrolls, "{size:?}");
            // The bar is 10 wide at the scrollable's right.
            let right = shown.x + shown.width;
            assert!(
                card.x + card.width <= right - 10. - 0.5,
                "{size:?}: the card's right edge {} under the bar at {right}",
                card.x + card.width
            );
            if !scrolls {
                // The page's row, 1060 at most, as far from either side.
                let row = *(laid.boxes.iter())
                    .filter(|b| (b.width - 1060.).abs() < 0.5 && b.contains(card.center()))
                    .min_by(|p, q| p.height.total_cmp(&q.height))
                    .unwrap_or_else(|| panic!("{size:?}: no row"));
                assert!(
                    ((row.x - shown.x) - (right - row.x - row.width)).abs() < 1.,
                    "{size:?}: {row:?} off centre in {shown:?}"
                );
            }
        }
    }

    /// The empty Work page's scroll bar, there only in a window too short for
    /// the page, takes its own room beside the "Your workspace is empty"
    /// panel rather than being drawn over its edge; where the page fits there
    /// is no bar and the panel spans the whole width as before (LIO-329).
    #[test]
    fn the_empty_work_pages_scroll_bar_is_beside_its_panel() {
        let dir = tempfile::tempdir().unwrap();
        let mut a = App::from_workspace(dir.path().join("w.json"), None);
        a.page = Page::Work;
        for (size, scrolls) in [
            (iced::Size::new(1093., 536.), true),
            (iced::Size::new(1093., 614.), true),
            (iced::Size::new(1440., 900.), false),
            (iced::Size::new(1920., 1040.), false),
        ] {
            let _ = a.update(Message::Resized(size));
            let laid = laid_out(&a, size);
            let heading = (laid.texts.iter())
                .find(|(t, _)| t == "Your workspace is empty.")
                .unwrap()
                .1;
            let (shown, content) = *(laid.scrolls.iter())
                .find(|(b, _)| b.contains(heading.center()))
                .unwrap_or_else(|| panic!("{size:?}: the page does not scroll"));
            assert_eq!(content.height > shown.height + 0.5, scrolls, "{size:?}");
            let right = shown.x + shown.width;
            // The panel: within the scrollable, wider than its 730 column.
            let panel = *(laid.boxes.iter())
                .filter(|b| {
                    b.width > 800.
                        && b.contains(heading.center())
                        && b.x >= shown.x - 0.5
                        && b.x + b.width <= right + 0.5
                })
                .min_by(|p, q| p.width.total_cmp(&q.width))
                .unwrap_or_else(|| panic!("{size:?}: no panel"));
            if scrolls {
                // The bar is 10 wide at the scrollable's right.
                assert!(
                    panel.x + panel.width <= right - 10. - 0.5,
                    "{size:?}: the panel's right edge {} under the bar at {right}",
                    panel.x + panel.width
                );
            } else {
                assert!(
                    (panel.x - shown.x).abs() < 0.5 && (panel.x + panel.width - right).abs() < 0.5,
                    "{size:?}: {panel:?} not the whole of {shown:?}"
                );
            }
        }
    }

    /// The operation editor's Delete asks first, as a setup's does: Cancel
    /// keeps the operation, another selection closes the question, and
    /// Delete operation removes it. The question shows in place of the
    /// editor's commands, and the footer knows the page its status is from.
    #[test]
    fn deleting_an_operation_asks_first() {
        let dir = tempfile::tempdir().unwrap();
        let mut a = App::from_workspace(dir.path().join("w.json"), None);
        let _ = a.update(Message::OpenSample);
        let _ = a.update(Message::SelectOp(0));
        let count = a.doc.setup().operations.len();
        let _ = a.update(Message::AskRemoveOp);
        assert!(a.confirm_delete_op);
        let _ = a.view();
        let _ = a.update(Message::ConfirmDeleteOp(false));
        assert!(!a.confirm_delete_op);
        assert_eq!(a.doc.setup().operations.len(), count);
        let _ = a.update(Message::AskRemoveOp);
        let _ = a.update(Message::SelectOp(1));
        assert!(
            !a.confirm_delete_op,
            "another operation closes the question"
        );
        let _ = a.update(Message::SelectOp(0));
        let _ = a.update(Message::AskRemoveOp);
        let _ = a.update(Message::ConfirmDeleteOp(true));
        assert!(!a.confirm_delete_op);
        assert_eq!(a.doc.setup().operations.len(), count - 1);
        // A status belongs to the page it was set on: one that a page change
        // leaves as it was is an earlier page's.
        let _ = a.update(Message::Page(Page::Work));
        assert_eq!(a.status_page, Page::Work);
        let before = a.status.clone();
        let _ = a.update(Message::Page(Page::Tools));
        let expected = if a.status == before {
            Page::Work
        } else {
            Page::Tools
        };
        assert_eq!(a.status_page, expected);
        let _ = a.view();
    }

