    /// The fixture block faced 4 mm off the top on setup 1 and flipped onto that
    /// face on setup 2, which the starter vise holds on ±Y, 8 mm up (written
    /// on the setup directly, nothing is suggested). Background jobs run in
    /// line, as in the smoke run. Setup 2 is the active one.
    fn leftover_app(dir: &tempfile::TempDir) -> App {
        let (doc, mesh) = crate::post::fixture::flipped_after(1);
        vise_app(dir, doc, mesh)
    }
    /// `doc`, on `mesh`, its second setup held in the starter vise on ±Y at
    /// grip 8, in the setup editor of that setup.
    fn vise_app(
        dir: &tempfile::TempDir,
        mut doc: crate::model::Document,
        mesh: crate::mesh::Mesh,
    ) -> App {
        let mut a = fresh_app(dir);
        doc.adopt_holders();
        a.replace_document(doc, None);
        a.imported_mesh = Some(mesh);
        a.smoke_dir = Some(dir.path().to_path_buf());
        let id = first_of(&a, "Vise");
        let p = &mut a.doc.setups[1].p;
        for (k, v) in [
            ("holding", "Vise"),
            ("holder", id.as_str()),
            ("vise_axis", "Y"),
            ("vise_offset", "0"),
            ("vise_grip", "8"),
            ("holding_gap", "2"),
        ] {
            p.insert(k.into(), v.into());
        }
        let _ = a.update(Message::SelectSetup(1));
        let _ = a.update(Message::SetupEditor);
        a
    }
    /// The box setup 2 of `leftover_app` starts from, as simulating setup 1
    /// makes it.
    fn simulated_stock(a: &App) -> crate::mesh::Bounds {
        let mesh = a.imported_mesh.as_ref().unwrap();
        crate::simulation::prepare(&a.doc, mesh, 1, 0)
            .unwrap()
            .plan
            .stock
    }
    /// `flipped_after(3)` (setup 1 faces, pockets and contours the walls,
    /// but only down to `bottom` mm above the part's underside) in
    /// `vise_app`, setup 1 held in the starter vise too, on ±Y at grip 8.
    fn contoured_app(dir: &tempfile::TempDir, bottom: &str) -> App {
        let (mut doc, mesh) = crate::post::fixture::flipped_after(3);
        doc.setups[0].operations[2]
            .p
            .insert("bottom".into(), bottom.into());
        let mut a = vise_app(dir, doc, mesh);
        let id = first_of(&a, "Vise");
        let p = &mut a.doc.setups[0].p;
        for (k, v) in [
            ("holding", "Vise"),
            ("holder", id.as_str()),
            ("vise_axis", "Y"),
            ("vise_offset", "0"),
            ("vise_grip", "8"),
        ] {
            p.insert(k.into(), v.into());
        }
        a
    }
    #[test]
    fn the_setup_editor_shows_what_the_earlier_setups_left_the_vise_to_grip() {
        use crate::holding::Held;
        let dir = tempfile::tempdir().unwrap();
        // Setup 1's Contour takes only the top 5 mm of the walls. Turned
        // over, setup 2's vise grips 8 mm of what was that top, cut in part.
        let mut a = contoured_app(&dir, "35");
        let mesh = a.imported_mesh.clone().unwrap();
        // Before the job has run, only what needs no simulation is said, and
        // both setups count as checked.
        assert!(crate::ui::holding_lines(&a).is_empty());
        assert_eq!(crate::ui::held(&a), Held::Every);
        let _ = a.refresh_left_stock();
        assert!(a.known_stock(1).1);
        // Worked out: the editor says what the export says, in its words,
        // and the NC review page no longer counts setup 2 as checked.
        let lines = crate::ui::holding_lines(&a);
        assert!(
            lines[0].starts_with("Setup 2 cannot be held in the vise: setup 1, operation 3 removed the material the jaws grip on ±Y from 0 to 8 mm above the stock's bottom. Leave at least 8 mm of those sides uncut in setup 1, "),
            "{lines:?}"
        );
        let mut doc = a.doc.clone();
        doc.setups[1]
            .p
            .insert("origin".into(), "Model origin".into());
        let exported = crate::post::post_job(&doc, &mesh);
        let refused = exported.setups[1].result.as_ref().unwrap_err();
        let said: Vec<String> = lines.iter().map(|l| format!("Flipped: {l}")).collect();
        assert_eq!(refused, &said);
        assert_eq!(crate::ui::held(&a), Held::Mixed);
        assert!(!crate::ui::modelled(&a));
        let _ = a.view();
        // Gripping 3 mm, all of it cut through: the jaws close on the walls.
        // A change of the holding alone checks it again on the stock worked
        // out, without simulating the earlier setups again.
        let before = a.left_stock.before[1].clone().unwrap();
        let _ = a.update(Message::Edit(Target::Setup, "vise_grip", "3".into()));
        assert!(a.known_stock(1).1);
        assert!(a.current_checks().is_none());
        assert!(crate::ui::holding_lines(&a).is_empty());
        let _ = a.refresh_left_stock();
        assert!(std::sync::Arc::ptr_eq(
            &before,
            a.left_stock.before[1].as_ref().unwrap()
        ));
        assert!(a.current_checks().is_some());
        // They hold the stock there, but 3 mm of grip does not hold it
        // against setup 2's facing, 39 mm higher, with the vise's typical
        // 5000 N (LIO-167). Tightened to 10 kN, it does.
        let lines = crate::ui::holding_lines(&a);
        assert_eq!(lines.len(), 1, "{lines:?}");
        assert!(
            lines[0].starts_with("Facing: the cut could tip the stock out of the vise: about 191 N, 39 mm above the top of the jaws' contact, which is 2.9 mm high"),
            "{lines:?}"
        );
        assert_eq!(crate::ui::held(&a), Held::Mixed);
        let vise = a
            .doc
            .workholding
            .iter_mut()
            .find(|h| h.kind() == "Vise")
            .unwrap();
        vise.p.insert("force".into(), "10000".into());
        let _ = a.refresh_left_stock();
        assert_eq!(crate::ui::holding_lines(&a), Vec::<String>::new());
        assert_eq!(crate::ui::held(&a), Held::Every);
        // The jaws are drawn on those walls, the band 80.7 mm across them
        // (the Contour's 0.3 mm allowance), inside the 84 mm box.
        let held = a.known_held(1).unwrap();
        let across = held.band.dimensions()[1];
        assert!(across > 80.6 && across < 80.8, "{held:?}");
        assert!(held.stock.dimensions()[1] > 83.9);
        let jaws = crate::ui::holding_boxes(&a);
        assert_eq!(jaws.len(), 2);
        assert!(
            jaws.iter()
                .any(|j| (j.bounds.max[1] - held.band.min[1]).abs() < 1e-4),
            "{jaws:?}"
        );
        let _ = a.view();
    }
    /// The Geometry tab's holes of a Drill at several A angles: each read at
    /// the angle that cuts it, and read again when the angles change (the
    /// kept answer is keyed on them and on A's turn) (LIO-246, review 2).
    #[test]
    fn a_drill_at_several_angles_lists_its_holes_and_follows_the_angles() {
        let dir = tempfile::tempdir().unwrap();
        let mut a = fresh_app(&dir);
        let (mut doc, mesh) =
            crate::indexed::tests::radial_job("30, 90, 150, 210, 270, 330", &[0, 1, 2, 3, 4, 5]);
        doc.file = Some(crate::model::ModelFile {
            name: "radial-holes.3mf".into(),
            path: dir.path().join("radial-holes.3mf"),
            format: "3mf".into(),
            bytes: 0,
            thickness: None,
        });
        a.replace_document(doc, None);
        a.imported_mesh = Some(mesh.clone());
        a.page = Page::Work;
        let _ = a.update(Message::SelectSetup(1));
        let op = a.doc.setups[1].operations[0].clone();
        let holes = |a: &App| a.drill_holes(&op, &mesh).as_ref().clone().map(|h| h.len());
        assert_eq!(holes(&a), Ok(6));
        let walls = |a: &App| {
            a.pocket_holes(&op, &mesh)
                .as_ref()
                .as_ref()
                .map(|h| h.len())
                .ok()
        };
        assert_eq!(walls(&a), Some(6));
        // Two of the angles: two of the holes.
        a.doc.setups[1]
            .p
            .insert(crate::indexed::ANGLES.into(), "30, 90".into());
        a.doc.sync_turns(Some(&mesh));
        assert_eq!(holes(&a), Ok(2));
        assert_eq!(walls(&a), Some(2));
    }
    /// On a Drill at several A angles each row's remove drops its own hole:
    /// the tube's three pairs of holes at A 30, 90 and 150, read each in its
    /// angle's frame, all at the same centre there (LIO-246, review 3).
    #[test]
    fn each_remove_of_a_drill_at_several_angles_drops_its_own_hole() {
        let dir = tempfile::tempdir().unwrap();
        let (mut doc, mesh) = crate::indexed::tests::radial_doc(
            "radial-tube",
            "30, 90, 150",
            ("3.3", "45"),
            14.3,
            |x, _| (x - 20.).abs() < 2.2,
        );
        doc.file = Some(crate::model::ModelFile {
            name: "radial-tube.3mf".into(),
            path: dir.path().join("radial-tube.3mf"),
            format: "3mf".into(),
            bytes: 0,
            thickness: None,
        });
        let fresh = || {
            let mut a = fresh_app(&dir);
            a.replace_document(doc.clone(), None);
            a.imported_mesh = Some(mesh.clone());
            a.page = Page::Work;
            let _ = a.update(Message::SelectSetup(1));
            let _ = a.update(Message::SelectOp(0));
            a
        };
        let a = fresh();
        let op = a.doc.setups[1].operations[0].clone();
        let drilled = a.drill_holes(&op, &mesh).as_ref().clone().unwrap();
        let picked = a.pocket_holes(&op, &mesh);
        let picked = picked.as_ref().as_ref().unwrap();
        assert_eq!((drilled.len(), picked.len()), (3, 3));
        let rows: Vec<usize> = (drilled.iter())
            .map(|h| crate::ui::picked_row(picked, h).unwrap())
            .collect();
        let mut distinct = rows.clone();
        distinct.sort();
        distinct.dedup();
        assert_eq!(distinct.len(), 3, "{rows:?}");
        // Each says its angle, its X and Y the same in each angle's frame.
        assert_eq!(
            drilled
                .iter()
                .map(|h| crate::indexed::at_angle(h.a))
                .collect::<Vec<_>>(),
            [" at A30°", " at A90°", " at A150°"]
        );
        for (h, &i) in drilled.iter().zip(&rows) {
            let mut a = fresh();
            let _ = a.update(Message::DropHole(i));
            let op = a.doc.setups[1].operations[0].clone();
            let left: Vec<Option<f32>> = (a.drill_holes(&op, &mesh).as_ref().clone().unwrap())
                .iter()
                .map(|h| h.a)
                .collect();
            // The hole opposite stays picked, but no angle turns it up now.
            assert_eq!(left.len(), 2, "{left:?}");
            assert!(
                !left.contains(&h.a),
                "dropped row {i} at {:?}: {left:?}",
                h.a
            );
        }
    }
    /// "Stock after this setup" on an indexed setup with the bar in the
    /// chuck: the view shows the round bar as its four angles leave it, every
    /// angle's cuts (#288 with LIO-246).
    #[test]
    fn stock_after_an_indexed_setup_is_the_bar_its_angles_leave() {
        use crate::indexed::tests::{bar_job, cutter, faced_square, prism};
        let dir = tempfile::tempdir().unwrap();
        let mut a = fresh_app(&dir);
        let mesh = prism(30.);
        let mut doc = bar_job(
            &mesh,
            30.,
            "100",
            "-150",
            "90, 180, 270, 0",
            faced_square(&cutter("12"), &mesh),
        );
        doc.file = Some(crate::model::ModelFile {
            name: "square-bar.stl".into(),
            path: dir.path().join("square-bar.stl"),
            format: "stl".into(),
            bytes: 0,
            thickness: None,
        });
        a.replace_document(doc, None);
        a.imported_mesh = Some(mesh);
        a.smoke_dir = Some(dir.path().to_path_buf());
        a.page = Page::Work;
        a.selected = None;
        let _ = a.refresh_left_stock();
        let _ = a.update(Message::SelectSetup(1));
        let _ = a.update(Message::SetupEnd);
        let _ = a.refresh_start_mesh();
        let view = crate::ui::scene_viewport(&a).unwrap();
        let (volume, surface) = view.start_stock.expect("the stock setup 2 leaves");
        assert!(!surface.triangles.is_empty());
        // The bar along X, cut.
        assert!(volume.bar_x.is_some() && volume.remaining < volume.material);
        let (_, _, before) = a.start_source().unwrap();
        assert_eq!(before, (1, 1));
        let job = a.left_stock.job.clone().unwrap();
        let cuts: Vec<_> = job.cuts.iter().filter(|c| c.source < before).collect();
        assert_eq!(
            cuts.len(),
            a.left_stock.after[1].clone().unwrap().cuts.len()
        );
        // The Facing's cuts at each of its four angles: each angle's frame.
        let mut frames: Vec<_> = vec![];
        for c in cuts.iter().filter(|c| c.source == (1, 0)) {
            if !frames.contains(&c.frame) {
                frames.push(c.frame);
            }
        }
        assert_eq!(frames.len(), 4);
        let _ = a.view();
    }
    #[test]
    fn the_view_shows_the_stock_a_setup_leaves_when_its_end_is_selected() {
        let dir = tempfile::tempdir().unwrap();
        // Setup 1 faces, pockets and contours; setup 2, turned over, faces.
        let mut a = contoured_app(&dir, "35");
        // The cuts of the stock the 3D view shows with "Stock after this
        // setup" selected, by setup and operation (meshed in line here).
        let shown = |a: &mut App, si: usize| {
            let _ = a.update(Message::SelectSetup(si));
            let _ = a.update(Message::SetupEnd);
            let _ = a.refresh_start_mesh();
            let view = crate::ui::scene_viewport(a).unwrap();
            let (_, surface) = view.start_stock?;
            assert!(!surface.triangles.is_empty());
            let (_, _, before) = a.start_source().unwrap();
            let job = a.left_stock.job.clone().unwrap();
            let cuts: Vec<_> = job.cuts.iter().filter(|c| c.source < before).collect();
            // The very cuts the browser's picture of that stock is made of.
            let after = a.left_stock.after[si].clone().unwrap();
            assert_eq!(cuts.len(), after.cuts.len());
            let mut by: Vec<(u16, u16)> = cuts.iter().map(|c| c.source).collect();
            by.dedup();
            Some(by)
        };
        // Not worked out yet: the setup's box.
        assert_eq!(shown(&mut a, 0), None);
        let _ = a.refresh_left_stock();
        // Setup 1 leaves all three of its operations' cuts; setup 2 those
        // and its Facing's.
        assert_eq!(shown(&mut a, 0), Some(vec![(0, 0), (0, 1), (0, 2)]));
        assert_eq!(shown(&mut a, 1), Some(vec![(0, 0), (0, 1), (0, 2), (1, 0)]));
        let _ = a.view();
        // Selecting an operation, the setup editor or another setup leaves it.
        // Setup 2's Facing shows the stock it starts from, not its own cuts.
        let _ = a.update(Message::SelectOp(0));
        assert!(!a.setup_end);
        assert_eq!(a.start_source().unwrap().2, (1, 0));
        let _ = a.update(Message::SetupEnd);
        let _ = a.update(Message::SetupEditor);
        assert!(crate::ui::scene_viewport(&a).unwrap().start_stock.is_none());
        let _ = a.update(Message::SetupEnd);
        let _ = a.update(Message::SelectSetup(0));
        assert!(crate::ui::scene_viewport(&a).unwrap().start_stock.is_none());
        // Editing an operation of the setup drops it until the job is worked
        // out again, so a stale stock is never shown.
        let _ = a.update(Message::SelectOp(1));
        let _ = a.update(Message::Edit(Target::Operation, "stepdown", "1.5".into()));
        assert_eq!(shown(&mut a, 0), None);
        let _ = a.refresh_left_stock();
        assert_eq!(shown(&mut a, 0), Some(vec![(0, 0), (0, 1), (0, 2)]));
    }
    #[test]
    fn the_view_shows_the_stock_the_operation_in_focus_starts_from() {
        let dir = tempfile::tempdir().unwrap();
        // Setup 1 faces, pockets and contours; setup 2, turned over, faces.
        let mut a = contoured_app(&dir, "35");
        // The setups an operation's starting stock was cut by, and the
        // operations of each, as the 3D view gets it (meshed in line here).
        let shown = |a: &mut App, si: usize, oi: usize| {
            let _ = a.update(Message::SelectSetup(si));
            let _ = a.update(Message::SelectOp(oi));
            let _ = a.refresh_start_mesh();
            let view = crate::ui::scene_viewport(a).unwrap();
            let (_, surface) = view.start_stock?;
            assert!(!surface.triangles.is_empty());
            let (_, _, before) = a.start_source().unwrap();
            let job = a.left_stock.job.clone().unwrap();
            let mut by: Vec<(u16, u16)> = (job.cuts.iter())
                .map(|c| c.source)
                .filter(|s| *s < before)
                .collect();
            by.dedup();
            Some(by)
        };
        // Not worked out yet: the setup's box, as before.
        assert_eq!(shown(&mut a, 0, 2), None);
        let _ = a.refresh_left_stock();
        // The first operation starts from the block.
        assert_eq!(shown(&mut a, 0, 0), None);
        // The Contour starts from what the Facing and the Pocket leave, not
        // its own cuts; setup 2's Facing from all three of setup 1's.
        assert_eq!(shown(&mut a, 0, 2), Some(vec![(0, 0), (0, 1)]));
        assert_eq!(shown(&mut a, 1, 0), Some(vec![(0, 0), (0, 1), (0, 2)]));
        // Kept meshed: going back to the Contour draws it at once. Editing
        // the operation in focus keeps the stock it starts from; setup 2's
        // Facing, which starts after it, waits for the job to be worked out.
        let _ = a.update(Message::SelectSetup(0));
        let _ = a.update(Message::SelectOp(2));
        assert!(crate::ui::scene_viewport(&a).unwrap().start_stock.is_some());
        let _ = a.update(Message::Edit(Target::Operation, "bottom", "33".into()));
        assert!(crate::ui::scene_viewport(&a).unwrap().start_stock.is_some());
        let _ = a.update(Message::SelectSetup(1));
        let _ = a.update(Message::SelectOp(0));
        assert!(a.start_source().is_none());
        let _ = a.update(Message::SelectSetup(0));
        let _ = a.update(Message::SelectOp(2));
        let _ = a.view();
        // Editing one before it does, until the job is worked out again.
        let _ = a.update(Message::SelectOp(1));
        let _ = a.update(Message::Edit(Target::Operation, "stepdown", "1.5".into()));
        assert_eq!(shown(&mut a, 0, 2), None);
        let _ = a.refresh_left_stock();
        assert_eq!(shown(&mut a, 0, 2), Some(vec![(0, 0), (0, 1)]));
        let _ = a.view();
        // The camera fits the same scene in setup 2, in its vise, with the
        // simulation shown or not and the stock and its jaws shown or not.
        let _ = a.update(Message::SelectSetup(1));
        let _ = a.update(Message::SelectOp(0));
        let fit = |a: &App| crate::ui::scene_viewport(a).unwrap().scene_bounds();
        let regular = fit(&a);
        assert!(!crate::ui::framed_holding(&a).is_empty());
        let mesh = a.imported_mesh.clone().unwrap();
        a.simulation = Some(crate::simulation::prepare(&a.doc, &mesh, 1, 0).unwrap());
        assert!(a.active_simulation().is_some());
        assert_eq!(fit(&a), regular);
        let _ = a.update(Message::ToggleStock);
        assert!(crate::ui::holding_boxes(&a).is_empty());
        assert_eq!(fit(&a), regular);
        a.simulation = None;
        assert_eq!(fit(&a), regular);
    }
    #[test]
    fn the_browser_draws_the_stock_each_setup_starts_from_and_leaves_in_its_jaws() {
        let dir = tempfile::tempdir().unwrap();
        // Both setups are held in a vise. Setup 1 faces, pockets and
        // contours the top 5 mm of the walls; setup 2 has the part turned
        // over, so that cut band is at the bottom of its walls.
        let mut a = contoured_app(&dir, "35");
        // The drawn pixels that are green, a cut face's colour, and grey,
        // the jaws'.
        let count = |picture: iced::widget::image::Handle| {
            let iced::widget::image::Handle::Rgba { pixels, .. } = picture else {
                unreachable!()
            };
            let drawn = || pixels.chunks(4).filter(|px| px[3] > 0);
            let green = drawn()
                .filter(|px| px[1] > px[0].saturating_add(30))
                .count();
            let grey = drawn()
                .filter(|px| px[0].abs_diff(px[1]) < 4 && px[1].abs_diff(px[2]) < 4)
                .count();
            (green, grey)
        };
        let start = |si, a: &App| count(crate::ui::stock_picture(a, si, false).unwrap());
        let end = |si, a: &App| crate::ui::stock_picture(a, si, true).map(count);
        // Not simulated yet: each setup starts from its block in its jaws,
        // and nothing is drawn as what it leaves. Each is drawn once.
        for si in 0..2 {
            let (green, grey) = start(si, &a);
            assert!(green == 0 && grey > 100, "{green} {grey}");
            assert_eq!(end(si, &a), None);
        }
        let _ = start(1, &a);
        assert_eq!(a.stock_pictures.borrow().len(), 2);
        let _ = a.view();
        // Simulated: setup 1 still starts from its block; setup 2 starts
        // from what setup 1 left it, the walls' cut band green where its
        // jaws, which grip that band, leave it in sight.
        let _ = a.refresh_left_stock();
        assert_eq!(start(0, &a).0, 0);
        let (green, grey) = start(1, &a);
        assert!(green > 20 && grey > 100, "{green} {grey}");
        // What each leaves, in its jaws: setup 1's cut top, and setup 2's
        // faced side, from the very stock setup 2's start is drawn from.
        for si in 0..2 {
            let (green, grey) = end(si, &a).unwrap();
            assert!(green > 1000 && grey > 100, "{si}: {green} {grey}");
        }
        assert!(std::sync::Arc::ptr_eq(
            a.left_stock.after[0].as_ref().unwrap(),
            a.left_stock.before[1].as_ref().unwrap()
        ));
        assert_eq!(a.left_stock.surfaces.len(), 2);
        let _ = a.view();
        // A job of one setup: what it leaves is drawn too.
        let mut single = leftover_app(&dir);
        single.doc.setups.pop();
        let _ = single.refresh_left_stock();
        assert!(end(0, &single).unwrap().0 > 1000);
        // The example is not simulated: its setup is drawn as its block.
        let mut sample = app();
        sample.doc = Document::sample();
        assert_eq!(start(0, &sample).0, 0);
        assert_eq!(end(0, &sample), None);
    }
    #[test]
    fn a_new_left_stock_result_does_not_reuse_the_picture_of_an_earlier_job() {
        let dir = tempfile::tempdir().unwrap();
        let mut a = contoured_app(&dir, "35");
        let _ = a.refresh_left_stock();
        let first = crate::ui::stock_picture(&a, 0, true).unwrap();
        let drawn = a.stock_pictures.borrow().len();
        // The job is edited and its new result holds a stock at the address
        // of the old one, as one allocated after the old is freed can.
        let old = a.left_stock.clone();
        a.doc.setups[0].p.insert("note".into(), "edited".into());
        let key = a.left_key().unwrap();
        assert_ne!(key, old.key);
        a.left_stock = crate::LeftStock { key, ..old };
        let second = crate::ui::stock_picture(&a, 0, true).unwrap();
        assert_ne!(first.id(), second.id(), "the old picture was shown");
        assert_eq!(a.stock_pictures.borrow().len(), drawn + 1);
        // The same job asks for the same picture again.
        let again = crate::ui::stock_picture(&a, 0, true).unwrap();
        assert_eq!(second.id(), again.id());
    }
